"""Parametric female/male body generator driven by the maker sliders.

The torso is a single lofted surface of superellipse cross-sections; limbs are
swept tubes following the actual bone chain, so changing proportion sliders
moves the skeleton and the skin together.
"""
from __future__ import annotations

import math
import os

import numpy as np

from ..core import math3d as m3
from . import deform, detail, primitives as prim
from .mesh import Material, Mesh, Model
from .skeleton import SOLE_Y, Proportions, Skeleton, build_humanoid

TORSO_SEG_BASE = 44     # around
TORSO_RINGS_BASE = 62   # along
LIMB_SIDES_BASE = 24

#: How many rays every ``*_OUTLINE`` table stores per station.  It is the grid
#: the shape was measured on, so it is also the grid a ring has to be built on
#: (:func:`limb_sides`).
LIMB_RAYS = 24


def torso_dims() -> tuple[int, int]:
    return detail.even(TORSO_SEG_BASE, 16), detail.n(TORSO_RINGS_BASE, 24)


def limb_sides(rays: int = 0) -> int:
    """Segments round a limb's ring — **a multiple of the outline table's rays**.

    The angular twin of :func:`_sweep_params` (§7.220 fixed the same mistake
    along the chain).  :data:`ARM_OUTLINE` / :data:`LEG_OUTLINE` are
    :data:`LIMB_RAYS` rays wide, and the ring used to carry 12 vertices at the
    shipping detail level, so half of every station's measured shape was
    interpolated away.  What that cost is not a smoothness — it is the
    **features between rays**: the thigh's inner apex at the junction sits at
    x = 2.1 mm on the table's own rays and the 12-gon read **8.97**, i.e. the
    two thighs came out 17.9 mm apart where Origin's are 1.2 (§7.222).

    **Alignment, not resolution** — measured on that apex, sides 12 / 16 / 20 /
    24 / 32 / 36 / 48 give 8.97 / 4.71 / 3.44 / **2.91** / 3.85 / 3.93 /
    **2.91** mm.  The two multiples of 24 agree to the digit and 36 is worse
    than 24 with half again as many vertices: past the table's own rays there
    is nothing left to resolve, exactly as §7.208 found for the torso's.

    **A count is not an alignment, and this only ever set the count** (§7.291).
    Where the twenty-four vertices *land* is
    :func:`primitives.sweep_rings`'s: they have to be spaced by polar angle
    (``polar``) and in the frame the table was measured in (``frames``), or the
    ring is twenty-four samples of an interpolation of the table rather than of
    the table.  On the palm's fused section — the flattest on this body, and
    with the frames 8.2° apart — only four of the twenty-four sat on a ray, and
    the ring came back 12.7% narrower than its own table.

    *rays* is **that table's** own width, not a global (§7.236).  It used to be
    :data:`LIMB_RAYS` for every limb, which makes buying a finer table for one
    of them cost rings on all of them: measured, taking every limb to 48 costs
    **+5,040 vertices** (11,156 → 16,196) where the leg alone costs **+2,736**
    (→ 13,892), and the feature the finer table is for is one station on the
    thigh.
    """
    n = int(rays) or LIMB_RAYS
    return int(math.ceil(detail.n(LIMB_SIDES_BASE, n) / n) * n)


def sv(p: dict, key: str, default: float = 0.5) -> float:
    """Read a 0..1 slider."""
    v = p.get(key, default)
    try:
        return float(v)
    except (TypeError, ValueError):
        return default


def rng(p: dict, key: str, lo: float, hi: float, default: float = 0.5) -> float:
    """Read a slider remapped into [lo, hi]."""
    return lo + (hi - lo) * sv(p, key, default)


def mul(p: dict, key: str, lo: float, hi: float, default: float = 0.5) -> float:
    """A **multiplier** whose neutral is exactly 1.0, over the same [lo, hi].

    ``rng`` puts the midpoint of the range at the slider's neutral, and none of
    these ranges is symmetric about one: measured, every multiplier in this file
    sat between 1.01 and 1.05 with nothing touched (``build`` 1.02,
    ``hip_depth`` 1.03, ``thigh_thick`` 1.05, ``neck_length`` 1.05…).  They
    compound — ``build × hip_depth`` alone is 1.05 — and what they were
    multiplying is the **measured** section table, so a body with every slider
    at rest came out 5% away from the thing the table was copied from
    (§7.169: the buttock 6.5 mm behind Origin's, the thigh 2.7% wide).
    A slider is a deviation from the measurement; at rest it has to do nothing.

    Piecewise linear rather than a rescaled range, so both ends still reach the
    values they were authored to reach.
    """
    v = sv(p, key, default)
    return (lo + (1.0 - lo) * (v / 0.5) if v <= 0.5
            else 1.0 + (hi - 1.0) * ((v - 0.5) / 0.5))


def bi(p: dict, key: str, amount: float, default: float = 0.5) -> float:
    """Read a slider as a bidirectional offset in [-amount, +amount]."""
    return (sv(p, key, default) - 0.5) * 2.0 * amount


def opt(p: dict, key: str, default: int = 0) -> int:
    """Read a discrete choice (style index)."""
    try:
        return int(p.get(key, default))
    except (TypeError, ValueError):
        return default


def col(p: dict, key: str, default=(1.0, 1.0, 1.0)) -> tuple:
    """Read an RGB colour as a hashable tuple."""
    c = p.get(key)
    if not c:
        return tuple(round(float(x), 4) for x in default)
    return tuple(round(float(x), 4) for x in tuple(c)[:3])


