#
# t runs across the **torso segment's own extent** (0.5144 to 0.8711 of stature
# on Origin's body), not from the crotch: §7.160 measured it the latter way, §7.164
# moved it to the segment, and this comment went on describing the old span for
# five sections.  The distinction is not cosmetic — the crotch is 0.038 of
# stature lower, and reading a table against the wrong span shifts every row by
# two stations (the first three then land where nothing but thigh exists).
#
# ``--shaped`` since §7.175: the body is authored against the armature the
# editor's **neutral pass** leaves (§7.172), so the target has to be Origin's body
# in that same pose.  Against the raw bind these radii were a uniform ~4% small
# — one cause, visible as every landmark being short by about a tenth.
#
# Radii are fractions of **stature** (see ``skeleton.BIND_REF`` for why not the
# body renderer's own height) and the section is cut through ``torso | head |
# leg`` — the labels whose skin the trunk's **surface** runs into at its two
# ends, and nothing else (``body_profile.section_selection``).  ``deltoid`` is
# deliberately out: with it the top four stations report the shoulder's
# half-width instead of the ribcage's.
#
# The numbers this replaced were hand-written and had no source, which is what
# ``CLAUDE.md`` 一之四 forbids.  Measured against them, our old trunk was
# 25–40% too thick through the waist and 50% too wide at the shoulders.
# --------------------------------------------------------------------------
#
# Reproduce with ``--part torso`` (not ``--part trunk``): the trunk selection
