# --------------------------------------------------------------------------
# The trunk's outline where a superellipse cannot follow it, as a **ratio**
# against the superellipse ``TORSO_PROFILE`` already fits — so rx/rz/n and every
# band slider keep working and this only puts back the shape the fit throws
# away.  48 stations x 24 rays, sliced off ``o_body_a``'s triangles with the
# same selection ``TORSO_PROFILE`` was measured with (``torso | head | leg``),
# about the same centre.
#
#   python tools/body_profile.py --part torso --span part --slices 48 \
#          --outline --shaped --emit
#
# The ray radii come from **cutting the triangles** with the section plane and
# taking the farthest crossing outward, not from binning vertices by angle: a
# 15° wedge across a cleft holds its floor and both its lips, and any high
# percentile answers with the lips.  Measured both ways on the same station,
# the gluteal cleft reads 0.82 of the fitted ellipse by wedge and 0.64 by
# intersection — 17 mm against 34 mm, on the one feature the table exists for.
#
# Where the fit is wrong, and by how much: the front midline (ray 6) dives to
# **0.7750 / 0.7090 / 0.6571** at t = 0.6771 / 0.6979 / 0.7188 (the cleavage — a
# superellipse ring has to put the section's deepest point on the midline, which
# is why our chest came out as one smooth barrel once the double-counted bust
# deformer was removed, §7.169 九之七), and the back midline (ray 18) runs
# **0.0588 / 0.3447 / 0.4844 / 0.5561 / 0.6290** at t = 0.0521 / 0.0729 / 0.0938
# / 0.1146 / 0.1354 — the gluteal cleft, deepening monotonically downward.
#
# **A ray that finds nothing stays at 1.0** — that is the superellipse, i.e. no
# claim for that direction, and never a neighbour's ratio (that would smear the
# cleavage up onto the collarbone).  Ten stations are partial that way, and
# since §7.294 they are **all** at 0.7604 and above, where the deltoid and the
# arm own the surface and this selection deliberately leaves them out (50–92% of
# the rays land).  The crotch ones used to be partial for the opposite reason —
# the
# thigh owned the surface and the selection left *that* out too — and adding
# ``leg`` closed them: t = 0.0521 went from 12/24 rays to 24/24, and its ratios
# from a flat 0.04 (the ring collapsed to a sliver, which the union with the leg
# envelope then covered for) to the row below.
#
# The two rows below the junction are all 1.0 and **must not be read**: down
# there the body is two thighs, so no ring, no centre and no ratio about one
# centre exists.  They are listed in ``TORSO_UNMEASURED_T`` and ``build_torso``
# and :func:`_outline_ratio` both drop them; the profile table has no rows there
# at all.
#
# The top station is one of the ten (19 of 24 rays), and it used to be far worse
# — ratios up to **1.2592**, all of it the neck skin the bone-group selection cut
# away (§7.233).  With ``head`` in the selection it reads 0.97–1.12, i.e. the
# neck really is close to the superellipse the profile fits.
# --------------------------------------------------------------------------
