# Anatomical markers in the loft's own t, derived from the same measurement:
# the hip is the widest section below the waist, the waist the narrowest of the
# middle, the bust the deepest above it, the shoulder the top of the deltoid.
# ``T_UNDERBUST`` is gone — it had no call site and no source.
_TRUNK = (0.5144, 0.8711)                      # trunk base, trunk top, of stature

# Stations the section ruler cannot measure, so the loft does not read them.
#
# At t = 0.0208 the slab holds ~1,400 vertices of vulva, buttock and thigh, and
# the fit says so in a different way on each body: the female section's centre
# comes back 8 mm off a midline it is symmetric about (every other station is
# within 1e-5), and the male one fits ``n = 5.824`` where its neighbours are
# 1.6–3.8.  ``--outline`` already judges this station "not a closed loop" and
# returns all 1.0 for it — **one ruler said unmeasurable and the other copied
# the number down**, which is what put a visible ring here.
#
# What it looked like: the row is 14% narrower than its neighbour, and on the
# male body ``n = 5.824`` pushes the 45° corners out 6.7% relative to a round
# section — a *square* groove across the crotch, plainly visible in
# ``preview/f0_male``.  The female body has the same 22% narrowing but at
# ``n = 2.7``, so it reads as a soft taper and nobody noticed for two sections.
#
# Dropped rather than smoothed: ``smooth_profile`` clamps below its first key,
# so the loft holds the lowest measured section down to its base — which is the
# part §7.169 P2 hands to the hip closure anyway.
#
# §7.235 re-measured the tables on **48** stations, so the single station this
# used to name is now two (0.0104 / 0.0312).  Both are still the same place —
# below ``junction`` at t = 0.0479, i.e. under the loft's own base — and
# ``--outline`` still judges both "not a closed loop" (2/48 stations all 1.0),
# which is the two rulers agreeing rather than one copying the other.
TORSO_UNMEASURED_T = (0.0104, 0.0312)


def _outline_ratio(t: float, theta: np.ndarray, male: bool = False) -> np.ndarray:
    """:data:`TORSO_OUTLINE` sampled at loft parameter *t* and polar angle.

    Bilinear: linear in ``t`` between stations (clamped at the ends) and linear
    in the angle, which wraps.

    ``TORSO_UNMEASURED_T`` is dropped here as well as in :func:`build_torso`.
    Those two stations are below the junction, where the body is two thighs and
    no ring about one centre exists, so their rows are a flat 1.0 — the
    superellipse, i.e. no claim.  Interpolating towards **that** would take the
    cleft out of the bottom of the seat; clamping to the lowest measured
    station instead carries it down, which is the direction it really goes.

    *male* picks :data:`TORSO_OUTLINE_M`.  The two tables differ on three
    stations only, but those three are the chest: the female front midline dives
    to 0.60 there and putting that on a male torso carves a cleavage into it.
    """
    src = [r for r in (TORSO_OUTLINE_M if male else TORSO_OUTLINE)
           if r[0] not in TORSO_UNMEASURED_T]
    ts = np.array([r[0] for r in src])
    tab = np.array([r[1] for r in src])
    k = int(np.clip(np.searchsorted(ts, t) - 1, 0, len(ts) - 2))
    u = float(np.clip((t - ts[k]) / max(ts[k + 1] - ts[k], 1e-9), 0.0, 1.0))
    row = tab[k] * (1.0 - u) + tab[k + 1] * u
    n = len(row)
    a = (np.asarray(theta) % (2.0 * np.pi)) / (2.0 * np.pi) * n
    i0 = np.floor(a).astype(int) % n
    i1 = (i0 + 1) % n
    f = a - np.floor(a)
    return row[i0] * (1.0 - f) + row[i1] * f


def torso_rings(ts, ys, unit: float, male: bool = False, seg: int = 0,
                slim: float = 1.0):
    """What :data:`TORSO_PROFILE` and :data:`TORSO_OUTLINE` say the trunk is.

    The superellipse from the profile table with the outline ratios put back,
    at loft parameters *ts* and world heights *ys* — i.e. the rings
    :func:`build_torso` starts from, **before** the union with the thigh
    envelope, before the hip closure and before the global smooth.

    Split out so a ruler can ask the tables the same question it asks the mesh.
    Without that column a row of ``--field`` cannot say whether it is off
    because the table does not describe Origin there or because the mesh does not
    reproduce the table, and those are opposite jobs (``CLAUDE.md`` 七; it is
    the same reason ``--vs-table`` grew its ``tab`` column in §7.196, which
    answers it for ``rx``/``rz`` but not per angle — and the seat's deficit is
    entirely per angle).

    Returns ``(rings, cz)``: ``rings[i]`` is an ``(seg, 3)`` ring in world axes
    with ``y`` already set, ``cz[i]`` the centre offset its ratios are about.
    """
    seg = seg or torso_dims()[0]
    ts = np.asarray(ts, dtype=np.float64)
    ys = np.asarray(ys, dtype=np.float64)
    table = [k for k in (TORSO_PROFILE_M if male else TORSO_PROFILE)
             if k[0] not in TORSO_UNMEASURED_T]
    rx = prim.smooth_profile(_extend_to_zero([(k[0], k[1]) for k in table]),
                             ts) * unit * slim
    rz = prim.smooth_profile(_extend_to_zero([(k[0], k[2]) for k in table]),
                             ts) * unit * slim
    # **Not** ``_extend_to_zero``: that carries a column down along its own
    # slope, which is right for a length and wrong for a shape exponent.
    # ``n`` runs 4.874 → 2.993 over the first two stations, so extrapolating it
    # to the loft's base gives **7.69** — a section with square corners, and
    # §7.176 dropped a station for reaching 5.824.  Measured at t = 0.0157, that
    # put the back diagonals 21 mm outside Origin's own seat.  ``smooth_profile``
    # clamps below its first key, which is the claim that can be defended: the
    # bottom of the loft is as round as the lowest station we measured.
    nn = prim.smooth_profile([(k[0], k[3]) for k in table], ts)
    cz = prim.smooth_profile(_extend_to_zero([(k[0], k[4]) for k in table]),
                             ts) * unit
    # **By polar angle, not along the superellipse's parameter**, and phased so
    # a vertex lands exactly on the front and back midlines.  Both matter for
    # the same reason: the two things a superellipse cannot hold — the cleavage
    # and the gluteal cleft — are on those midlines, and they reach the mesh
    # only through :data:`TORSO_OUTLINE`, which is measured on rays at uniform
    # polar angle about this same centre.
    #
    # Stepping the parameter instead samples that table wherever the curve's
    # own parameterisation happens to land, and on a boxy section that is
    # nowhere near uniform: at t = 0.0625 (n = 4.874) the ring's vertices ran
    # 216.50, 221.89, 230.42, **270.00** — a 39.58° hole straight through the
    # cleft, spanned by one chord.  Measured, that chord read 85.3 mm from the
    # body axis at θ = 255 where Origin's buttock is at 130.2 (§7.208).  The table
    # itself was right there all along: ``ratio × fit`` matches Origin's own
    # section to ±1.7 mm across 225–315 (worst −12 mm, in the transition).
    #
    # ``π/2`` rather than half a step, so the midline vertex survives every
    # detail level: half a step only lands on 90° when ``seg/2`` is odd (34
    # yes, 44 no).
    rings = []
    for i in range(len(ts)):
        ring = prim.superellipse_ring(seg, rx[i], rz[i], nn[i],
                                      (0.0, ys[i], cz[i]),
                                      phase=math.pi / 2.0, polar=True)
        rel = ring[:, [0, 2]] - np.array([0.0, cz[i]])
        ratio = _outline_ratio(float(ts[i]),
                               np.arctan2(rel[:, 1], rel[:, 0]), male)
        xz = np.array([0.0, cz[i]]) + rel * ratio[:, None]
        ring[:, 0], ring[:, 2] = xz[:, 0], xz[:, 1]
        rings.append(ring)
    return rings, cz


# --------------------------------------------------------------------------
# The trunk does not end at a height — it ends at a **rim**, and that is why
# both §7.232's reading of this gap and its proposed fix were wrong.
#
#   python tools/body_profile.py --neck --emit
#
# ``o_body_a``'s neck hole is a slanted 26-gon running 0.8646..0.8825 of stature
# (30.7 mm), lowest at the front and highest at the nape, and it is the same
# curve on both sexes to five decimals.  Above 0.8646 every horizontal cut has
# **two open ends**, so no ring can describe it — extending ``TORSO_PROFILE``'s
# span to the surface's top, which is what §7.232 proposed, would add three
# stations of open arc.  That is §7.220's mistake at the other end of this loft.
#
# It also says the error was two-sided, and that is why five sections of
# half-width-per-height tables never showed it: our flat top at ``trunk_top``
# was **7.4 mm too tall at the front** and 22.8 mm too short at the back
# (mean −9.9, |d| p50 11.8 over 24 rays).  A table of "how wide is Origin at this
# height" only ever sees the second half.
#
# Stored the way :data:`TORSO_OUTLINE` is — resampled onto our own 24 rays and
# **as ratios**, not as Origin's 26 rim vertices (``CLAUDE.md`` 一之四之一: a
# measurement resampled onto our grid is a fact, a copy of somebody's vertices
# is their expression).  ``dy`` is above the cap in stature, ``ratio`` is
# against the cap ring's own radius in that direction, so the band rides
# whatever the profile tables and the sliders make the neck.
NECK_RIM = [
    (0.01131, 0.9590),
    (0.00881, 1.0195),
    (0.00623, 1.0419),
    (0.00407, 1.0329),
    (0.00222, 1.0212),
    (0.00079, 1.0105),
    (0.00000, 1.0054),
    (0.00079, 1.0105),
    (0.00222, 1.0212),
    (0.00407, 1.0329),
    (0.00623, 1.0419),
    (0.00881, 1.0195),
    (0.01131, 0.9590),
    (0.01378, 0.9248),
    (0.01537, 0.8572),
    (0.01645, 0.8111),
    (0.01727, 0.8016),
    (0.01779, 0.8154),
    (0.01796, 0.8254),
    (0.01779, 0.8154),
    (0.01727, 0.8016),
    (0.01645, 0.8111),
    (0.01537, 0.8572),
    (0.01378, 0.9248),
]


def _neck_rim(theta: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    """:data:`NECK_RIM` sampled at polar angle — ``(dy, ratio)``.

    Linear and wrapping, the same as :func:`_outline_ratio`, and about the same
    centre: the rim was measured on rays from the cap section's own axis.
    """
    tab = np.asarray(NECK_RIM, dtype=np.float64)
    n = len(tab)
    a = (np.asarray(theta) % (2.0 * math.pi)) / (2.0 * math.pi) * n
    i0 = np.floor(a).astype(int) % n
    i1 = (i0 + 1) % n
    f = (a - np.floor(a))[:, None]
    row = tab[i0] * (1.0 - f) + tab[i1] * f
    return row[:, 0], row[:, 1]


# The shoulder junction's own shape, in the arm axis' cylinder (§7.248).
#
# The arm tube and the trunk meet by crossing, and ``weld`` sews the two trimmed
# openings with **one row of quads** — which is a ruled surface, i.e. straight
# by construction along the band.  Measured against ``o_body_a``, Origin is not: at
# the top of the shoulder its radius about the arm axis dips ~2 mm below the
# chord and then climbs, the saddle §7.247 read off the silhouette.
#
# Each row is one ray, 24 of them from the ring's own centre with ray 0 up and
# turning towards the back; the entries are ``r / Origin's own radius at the arm
# end`` at s = 1/10 .. 1 across the band (s = 0 is 1.0 by construction).  A
# ratio, and against Origin's own arm end rather than against our chord, so the
# table says only what Origin's *shape* is and rides whatever the profile tables and
# sliders make the rings (:data:`NECK_RIM`'s form, ``CLAUDE.md`` 一之四之一).
# Measured, our arm ring lands on Origin's to **-0.21 mm** mean, so that end is a
# sound thing to hang it on; the trunk end is not (see :data:`SHOULDER_RINGS`).
#
# ``None`` is a ray this cannot be measured on, and it is the armpit's whole arc
# — where the ray from the axis grazes the crease instead of crossing it, the
# axial coordinate stops being the curve's parameter and a swept ring stops
# describing the surface.  Same wall §7.238 hit from the other side.
#
# **Re-measured in §7.291**, because this table's rays live in a frame
# ``weld.band_frame`` takes from **our own two loops** — so when the arm's ring
# moved (its vertices went onto the outline table's rays), the rays this is
# sampled on moved with it and the stored values stopped describing the same
# directions.  Read on the old table the trunk rim came out **+2.06 mm** mean
# and +9.95 worst; ``--gaps``' deltoid went 1.10 → 1.98 mm.  The one ray this
# now withholds (theta 135) is the armpit's arc growing by one ray, not a
