#: How many rows of the trimmed part's own surface, behind its rim, the band
#: places as well.
#:
#: **Rows, not a distance.**  The band's axis is nearly horizontal, so a slab
#: of constant *s* is a near-vertical plane through the shoulder and it grazes
#: the whole flank: measured, ``s in (1, 1.1]`` picks up 42 trunk vertices
#: spread from y=0.564 to y=0.855 with radii out to 432 mm — a strip down the
#: side of the body, not a neighbourhood of the junction.  Counting rows along
#: the surface has no threshold in it and gives what §7.257 asked for: row 1 is
#: 41 vertices, y 0.795‥0.854, a median **9.6 mm** inboard, which is inside the
#: 6‥12 mm the deficit was measured to die out over.
#: **One, and that is measured** (§7.260) — more rows do not carry anything,
#: they cost.  ``--creases`` over the whole female body against the number of
#: rows: 0 → 3,826, **1 → 3,817**, 2 → 3,824, 3 → 3,841; and the slab the
#: second row was asked for, y=0.850, reads 30 / **29** / 28 / 30, i.e. one
#: edge for seven elsewhere.  The fold there is not the row's to carry
#: (§7.260 三).
SHOULDER_TAIL_ROWS = 1


#: Interior rings the band is built with.  0 is the plain strip, which is what
#: this was until §7.248 measured the price:
#:
#: ===== ======== ================== =========================
