#: ===== ======== ================== =========================
#: 0     11,428   2.67 mm            48.9 %
#: 1     11,476   2.16               39.2
#: 2     11,524   **1.94**           **38.1**
#: 3     11,572   1.89               38.1
#: ===== ======== ================== =========================
