# stature deep (a heel, caught because the skin chain ran on into
# ``cf_j_foot``) and now reads 0.018, tapering into the ankle.
#
# Kept as constants rather than deleted: they are the mechanism for "the table
# covers less of the chain than the sweep does", and an axis that ends
# somewhere else would need it back.
ARM_TIP, LEG_TIP = 1.0, 1.0

# What the ellipse above cannot hold, as a **ratio** against it — the limb's
# half of :data:`TORSO_OUTLINE`, and measured the same way:
#
#   python tools/body_profile.py --limb leg --stations 28 --shaped --outline
#
# ``_limb_sections`` gives every station an ``r1``/``r2``, and an ellipse has to
# put its widest point on an axis — so the adductor bulge on the inner front of
# the thigh is exactly what that fit throws away.  Measured, the thigh's outline
# runs 0.83 to 1.10 of its own fitted ellipse, and where the shortfall showed is
# **not** where the ellipse is worst: a ray from the body axis at 30-40° grazes
# the inner front of the thigh, so a few per cent of radius there is where "the
# crotch has a hard-edged rectangle" came from (§7.192 三: at 0.500 of stature,
# θ = 30, both bodies read *leg* and ours was 20.4 mm short; at θ = 40 Origin has a
# thigh and we had no surface at all).
#
# Rays are ``k/24·2π`` in the limb's own frame — the one ``o1``/``o2`` live in,
# taken about the **measured centre**, not the vertices' median.  Ratios about
# any other origin would store that offset a second time as shape.
#
# Two stations are withheld rather than filled (t = 0.0536 and 0.7679, and the
# latter is past ``LEG_TIP`` anyway): their rings have a 165° / 225° hole, so
# ``o1``/``o2`` are not measurable either and the generator holds a neighbour's
# offset there — a ratio taken about this centre would then be read about a
# different one.  That is not §7.186's mistake: the gate that node removed threw
# away rays measured about a centre the generator *does* use.
