# Nothing past the tip **for this table**: the axis ends at ``cf_j_middle01``,
# a knuckle, and past it the section about this axis is two to four separate
# closed curves, so no ring can describe it (§7.252 counted them; the same
# sentence as §7.190's "a star-shaped ring cannot hold two lobes").  Kept as a
# constant for the reason ``ARM_TIP``/``LEG_TIP`` are (see there).
#
# What used to stand here was "the fingers are their own chains from there",
# which is true about the **bones** and false about the **surface** — Origin's skin
# is still fused 0.157 of this axis past the knuckle.  :data:`HAND_WEB` is that
# stretch, measured.
PALM_TIP = 1.0

#: Where the thumb leaves — the most distal station at which a plane
#: perpendicular to this axis still cuts palm **and** thumb as one closed curve
#: (§7.288).  Bisected, so it has no threshold and no scan-grid rounding, the
#: same topological criterion :data:`BIND_REF`\ ``["junction"]`` uses at the
#: crotch.  Both sexes report it identically (the two hands are the same bind
#: geometry, §7.244).
#:
#: It is not a parameter of the sweep — the sweep runs to :data:`PALM_TIP` — it
#: is what says which stations of :data:`PALM_SECTIONS` describe the fused
#: section, and therefore which interdigital pairs are already bridged by the
#: palm's own tube.  ``--fork`` prints it as the first branch's ``t1``.
PALM_FUSED_TIP = 0.7741

# What that ellipse cannot hold:
#
#   python tools/body_profile.py --fork --stations 48 --emit
#
# A palm is the least elliptical section on the body, and over the fused stretch
# it is not even close: the section is palm **and** thumb with the first web
# space between them, so the ratio runs **0.24 to 1.20** of its own fitted
# ellipse and the minimum falls as the two draw apart (0.83 at the wrist, 0.55
# at t = 0.46, 0.24 at 0.74 — the notch deepening as the thumb leaves).  Past
# the fork the thumb is gone and the old reading returns: 0.49 to 1.25, low on
# one whole flank because the palm is deeper on the thumb side than on the
# little-finger side.  Neither is something an ellipse can hold; that is what
# these rows are for.
#
# **24 rays is 24 rays even when the shape is a peanut.**  ``limb_sides()``
# rounds the ring up to a multiple of :data:`LIMB_RAYS`, so the notch is sampled
# by whatever rays fall in it and nothing is interpolated away between them
# (§7.222); ``--fork``'s ``mul`` column is the test that a ring about one centre
# can carry the station at all, and it is 0 on every one of these.
