# The nipple, cut with the same plane as every other chain:
#
#   python tools/body_profile.py --limb nipple --skin torso --stations 24 \
#       --shaped --emit
#
# **F0-2 (i).**  Three of the editor's sliders — ``AreolaBulge``, ``NipWeight``
# and ``NipStand`` — moved 794 / 742 / 510 of Origin's vertices and **0** of ours,
# because this geometry did not exist (§7.202).  What blocked building it was
# not the shape but the *place*: the neutral pass was writing the bust chain's
# position unscaled, so on the default figure ``cf_j_bnip02`` stood 21 mm in
# front of our own breast surface and anything put there would have floated
# (§7.203).
#
# **``--skin torso`` is the whole of why this table is reproducible** (§7.254).
# The surface about this axis is the breast, weighted to ``cf_s_bust*``, so the
# chain's own selection finds it at 6 stations out of 24 — and the five rows
# that fixed that in §7.212 were measured by a script outside the project, so
# for forty nodes ``--emit`` could not reproduce what is written here.  With the
# selection in the tool the whole table comes off one ruler in one command, and
# the two selections agreeing is a **calibration** rather than an assumption:
# every station the chain can also reach comes back the same to five decimals
# (0.00927 / 0.00916 at 0.6458, 0.00676 / 0.00680 at 0.7708, 0.00225 / 0.00222
# at 0.9792 — the whole overlap, not just the join §7.212 could check).
#
# ``r1`` and ``r2`` agree to within 6% at every station — a nipple is round, so
# the sweep takes ``squash`` from the table like everything else and it comes
# out ≈1.  Origin labels **zero** vertices ``nipple``; they are all torso, and this
# is one continuous taper out of the breast rather than a separate object.
#
# **Both endpoint rows are here now.**  The table used to run 0.6200..0.9792 —
# cell centres of a grid that started where the sweep starts — and
# ``_limb_sections`` interpolates with ``np.interp``, which holds the outermost
# value flat: our last ring carried 0.00225 where Origin's t = 1.0 section is
# 0.00182, **+23.6%**, and then the typed cone below was applied on top of that.
# §7.209 cut endpoints for every other chain and §7.246 added the five digits'
# missing t = 1.0 rows; this chain was left out of both because its sections
# could not be measured at all.
#
# **The male body has no nipple to measure** — the ``if sex == 0`` gate in
# :func:`build_body_mesh` is that measurement, not a preference; the numbers are
# there.  So one table for both sexes is not claimed, and there is nothing to
# claim it about.
