# **How the nipple closes**, over :data:`NIPPLE_REACH` past ``cf_j_bnip02``:
#
#   python tools/body_profile.py --tip --limb nipple --skin torso \
#       --stations 24 --emit
#
# Same columns and same units as :data:`DIGIT_TIP` — *f* of the reach, ``r1`` /
# ``r2`` as fractions of the chain's own t = 1.0 section, ``o2`` in units of the
# reach — because it is the same ruler and the same consumer.
#
# It replaces the second typed cone on this body: ``radii[-1] × 0.80`` at 0.6 of
# the reach and ``× 0.28`` at the end, with a flat fan disc on that.  §7.244
# measured that construct away on the five digits, where it was the hand's worst
# row; the nipple kept it, because ``--tip`` walks ``--limb`` and ``--limb``
# could not see this chain.  Measured, the typed numbers were **+19%** at f =
# 0.60 (0.80 against 0.673) and the end never closes at all (0.28 against 0.0),
# so a 0.6 mm flat disc stood where Origin comes to a point.
#
# ``r1`` and ``r2`` agree to 0.004 the whole way down — the tip is round, unlike
# a fingertip, which is flatter than it is narrow.  Left against right is 0.0024
# (p50), this ruler's noise floor.  ``o2`` is a **measurement of nothing much**:
# its largest row is 0.067 of a 0.74 mm reach, 0.05 mm, and it is not monotone,
# so read it as "the tip does not drift" rather than as a curve.  It is carried
# rather than zeroed because a 0 is a claim too (§7.186).
