# Where the sweep starts, as a fraction of the axis.  Behind the breast's own
# surface on purpose: measured, our skin crosses the axis at t = 0.688, so a
# base ring at 0.62 is **inside** the breast and its cap never shows.  Starting
# at the table's first station instead would leave the base ring standing proud
# of the skin with a visible rim.
NIPPLE_START = 0.62
PALM_SAMPLES_BASE = 14
# How far the palm's surface reaches **behind** ``cf_j_hand`` — the overlap
# with the forearm's tube, which ends at that same joint.  Measured the way
# :data:`DIGIT_REACH` is, at the other end of the chain: it is where Origin's wrist
# bones stop owning the surface, and 0.00351 of stature is 6 mm on the
# reference figure, enough that the palm's start cap sits inside the forearm.
#
# It is **not** where the hand's remaining "+15% length" comes from — that was
# checked, and the answer is that the number is not a measurement of the hand.
# Split at the joint, our fingertips reach 0.08012 of stature past ``cf_j_hand``
# against Origin's 0.08032 (**−0.2%**) and the whole difference is behind it, in
# vertices of the **forearm's** tube that fall nearest ``cf_s_hand`` and so
# count as "hand" in a dominant-bone selection.  A bounding box over a bone
# group measures the skinning as much as the shape (``CLAUDE.md`` 七 — a
# selection that differs between the two bodies is the ruler, not the mesh).
PALM_BACK = 0.00351

# --------------------------------------------------------------------------
# The trunk past the knuckle, and the three forks along it.  Measured with
#
#   python tools/body_profile.py --fork --stations 96 --emit
#
# **Origin's hand is one skin, and it sheds one digit at a time.**  ``--fork``
# bisects the stations where a plane perpendicular to the hand axis stops
# cutting a given digit inside the trunk's curve (§7.284 counted the stretches,
# §7.295 asked which of them a ring can express, §7.298 ranked them and §7.299
# priced what a one-centre ring fills in at each).  Between the knuckle line and
# the index fork there are 11.8 mm of trunk that no table on this body described:
# ``PALM_SECTIONS`` stops at :data:`PALM_TIP` and the four digits' tubes started
# at their own t = 0, which is why the palm's distal end was a **flat 25-vertex
# plate with four tubes crossing it** — 406.5 mm² projected, 24 of its vertices
# visible and 100% of their normals more than 30° off Origin's (§7.283/§7.288), the
# hand's first row on ``--vs-shape --pieces`` for six sections.
#
# One block per stretch over which the section is a single closed curve, because
# the section changes **discontinuously** at a fork (r1 runs 0.01878 → 0.01467
# across the little's and 0.01438 → 0.00996 across the ring's): the jump is the
# fork, and one interpolated table across it would draw a taper where Origin has a
# split.
#
# **Eight rows is not eight rings, at either end.**  The first is the cell the
# fork's strip takes (:data:`FORK_STRIP_STEPS`), and since §7.328 the last two
# are one: ``--fork`` insets its end rows off the fork by a fraction of the
# **branch**, so what is left between that row and the station before it is
# 0.28 mm here and 0.43 mm on the block below, against a cell of 1.30 — a
# residual set by where the fork falls in the scan grid, not a length either
# run names.  :data:`FORK_ROW_MERGE` drops the **inner** of the pair, and both
# rows stay in the table because they are what the scan measured; which of
# them becomes a ring is the generator's decision, the same way
# :data:`FORK_STRIP_STEPS` is.
#
# **The cell is the scan's, so a re-emit has to name it**: these rows stand on
# ``tools/body_profile.py --fork``'s own station grid, and that tool's default
# is **12** steps (the limb tables' count, assigned before its dispatch) — a
# 11.44 mm cell against the 1.43 mm these rows hold.  So a re-emit without
# ``--stations 96`` produces a table six times coarser and nothing says so.
# ``--fork`` prints which ``--stations`` this table stands on for that reason
# (§7.335), and the two subtractions above cost real rows: the ``ring`` block's
# four become **two**, which is no interior station at all and a ruled band
# between them — §7.331's finding on the foot, arrived at from the other side.
#
# ``own``/``host`` are §7.295's ``own t`` — where the fork plane cuts the
# **leaving** digit's own chain and the **staying** one's.  They are what says a
# digit's own tube must start part-way along itself: the trunk's ring draws
# everything proximal of the fork, which for these three is their proximal
# quarter to third and is what "fused" means.  ``host`` at the last fork is where
# the middle finger takes over from the trunk.
