         (1.0191, (0.9750, 1.1289, 1.1394, 1.0453, 0.9895, 0.9574, 0.9457, 0.9533, 0.9818, 1.0437, 1.2120, 1.1762, 0.9831, 1.0439, 0.5934, 0.7318, 0.9035, 0.9496, 0.9810, 0.9049, 0.7595, 0.6474, 0.9351, 1.0120)),
         (1.0422, (0.9772, 1.1451, 1.1580, 1.0625, 1.0001, 0.9688, 0.9573, 0.9698, 0.9975, 1.0574, 1.1641, 1.1573, 0.9975, 1.0607, 0.6018, 0.7439, 0.9189, 0.9502, 0.9822, 0.8987, 0.7488, 0.6314, 0.5466, 1.0096)),
