#: Vertices round a web's ring, once it has a table to read.  **Half** of
#: :data:`LIMB_RAYS` — a divisor, not the multiple :func:`limb_sides` rounds up
#: to.  Both put every vertex exactly on one of the table's rays, which is the
#: alignment §7.222 is about; a divisor simply reads every other one.
#:
#: Priced against the picture (§7.297), the hand close-up's side view, which is
#: the angle a web is broadside to.  ``>16 lv`` inside the silhouette / the
#: **surface** half of it, against the six-sided ellipse this replaced:
#:
#: ===========  =========  ==========  =========  ==============
#: sides        table      vertices    side       side, surface
#: ===========  =========  ==========  =========  ==============
#: 6            ellipse    11,914      13.06%     3.19%
#: 6            measured   11,914      12.56%     2.89%
#: 24           ellipse    12,994      12.77%     3.00%
#: **12**       measured   **12,274**  **11.82%** **2.29%**
#: 24           measured   12,994      11.60%     2.14%
#: ===========  =========  ==========  =========  ==============
#:
#: Twelve buys **85%** of what twenty-four does for a **third** of the
#: vertices, and the hand is the one segment already at Origin's own share of the
#: budget while the trunk is at seven tenths of it (N20, and §7.236 turned the
#: leg's finer outline down on the same argument).  What the skipped rays cost
#: is the other 15%: the table's extremes do not all sit on even rays (the
#: dorsal minimum is ray 7 and one flank peak is ray 21).
#:
#: Neither change is worth having alone — the ellipse at 24 sides is a smoother
#: wrong shape (12.77%) and the table at 6 sides has nowhere to put it
#: (12.56%) — which is §7.220's finding about a table and the grid that samples
#: it, in the angular direction.
WEB_SIDES = LIMB_RAYS // 2

# The same stations' **shape**, measured with the same command (§7.297).
#
# :data:`HAND_WEB` is two numbers a station and the ring built from them is an
# **ellipse** — semi-axis ``0.5 × gap`` on the line joining the two digit axes,
# ``half`` across it.  Only the second of those was ever measured; the first is
# where the two axes are, and what the surface does **between** them had never
# been asked.  Every other section on this body has that ratio table
# (:data:`ARM_OUTLINE`, ``LEG_OUTLINE``, :data:`PALM_OUTLINE`, …), and §7.253
# had already named the gap without measuring it: it priced the obvious suspect
# (tessellation — six sides against twelve draws the same wedge, +480 vertices,
# ``--vs-shape``'s >30° went *up*) and wrote "the ellipse's two poles land on
# the two finger axes and Origin is round there, so the ring creases where it
# leaves the tubes".
#
# **Measured, Origin is not round there — it is a groove**, and the ellipse has its
# maximum exactly where Origin has its minimum.  Twenty-four rays about the ring's
# own centre, index-middle at t = 1.0388: the ray across the bridge (90°) is
# **1.000 by construction** — that is the ray ``half`` was measured on — and
# the rays at 60° and 120° read **1.679** and **1.663**, i.e. the skin stands
# 5.1 mm further out a quarter of the way towards either finger than it does in
# the middle.  Ours reads 0.93-1.09 over the same rays, because ours *is* the
# ellipse.  Every station of all four pairs has the same sign.
#
# Rays 0, 6, 12 and 18 are 1.000 in every row and cannot be anything else: the
# two across the bridge are what ``half`` is measured along, and the two towards
# the axes are pinned by the bound below.  **So this table only moves the
# sixteen vertices between them** — which is the fillet, and is what the union
# with the two finger tubes crosses.
#
# About **eleven of the twenty-four rays are measured**; the rest left the
# section through one finger's far wall, and a radius read there is a fact about
# that finger.  The split is the definition of a bridge and not a threshold —
# the web is the surface *between* the two axes, so a ray owns its reading when
# its exit point's coordinate along the join is inside the pair.  The rest are
# filled the way :func:`tools/body_profile.py: limb_ratios` fills a ray that
# found nothing: wrapping interpolation from **this** section's own measured
# rays (§7.186 — a missing sample is not 1.0, and 1.0 beside a measured 1.68 is
# a step), bounded so nothing invented reaches past the digit axes or past the
# measured thickness.  That bound is the ownership rule again, and it is what
# makes the fill safe: the sweep is unioned with the two finger tubes, so a ring
# that stays inside the box the two axes make is hidden whatever it does there.
#
# ``thumb-index``'s rows are here for the same reason its thickness rows are: no
# tube reads them (the palm's own sweep draws that bridge since §7.288) and they
# are the measurement the skip is justified by.
