# How far each digit's surface carries on **past its last joint**, along that
# joint's own direction — the tip, which no chain reaches.  Printed by the same
# command as the table above ("surface reaches X past the last joint"); left
# against right agrees to 0.00006 of stature, which is this ruler's noise here.
#
# It replaced ``surf_span - bone_span``, which measured the same thing on the
# raw bind and was consumed as part of a Catmull-Rom span.
DIGIT_REACH = {"thumb": 0.01300, "index": 0.00923, "middle": 0.00966,
               "ring": 0.00986, "little": 0.00936}

# **How a fingertip closes**, over that reach.
#
#   python tools/body_profile.py --tip --emit --stations 24
#
# Rows are ``(f, r1, r2, o2)``: *f* is the fraction of :data:`DIGIT_REACH` past
# the last joint, ``r1``/``r2`` are the section's width and depth as fractions of
# **its own t = 1.0 section** (the row ``_limb_sections`` already hands the sweep
# as ``radii[-1]``), and ``o2`` is how far the section's centre has drifted, in
# units of the reach.  Scale-free on purpose: one table then serves both sexes
# and every value of the hand slider.
#
# This was the one stretch of the body nothing could measure.  A digit's last
# joint sits *inside* the fingertip, so ``--limb index`` stops 0.29 of a chain
# length short and the generator closed the gap by typing a cone: ``radii[-1] ×
# 0.82`` at 0.55 of the reach, ``× 0.30`` at the end, and a flat fan disc on
# that.  Measured against Origin the taper is the hand's worst row on every column —
# the last ring and its cap run **66-89%** of their normals more than 30° out on
# all five digits, because a cone is not a dome (§7.244).  ``--beyond`` cuts the
# missing stations; a typed shape where a ruler was missing is exactly what
# 一之四 forbids, and the ruler was the whole of it.
#
# **Per digit, not pooled**, and that is measured rather than assumed: left
# against right agrees to 0.0016 (p50, this ruler's noise floor on a symmetric
# body), while across the five digits ``r1`` at f = 0.60 spans 0.748-0.892 and
# ``o2`` spans a factor of **ten** — −0.011 on the thumb against −0.092…−0.115
# on the four fingers.  A thumb tip keeps its depth to f = 0.45 (``r2`` 1.008,
# 1.019, 0.997) and then collapses; a finger's falls from the start.  The two
# sexes agree to **0.0009** on every row, well inside that noise, so one table
# does for both (§7.153, as for every other limb table).
#
# ``o2`` is ``None`` on the last row because nothing measures where the tip
# *point* sits: the radii there are a measurement (the cut stops finding an
# outline, which is the same fact ``DIGIT_REACH`` reports), the centre is not,
# and a 0 would be a kink — the drift reaches −0.13 of the reach and would jump
# back onto the axis.  ``_limb_sections``'s withhold convention (§7.220) holds
# the last measured value instead (§7.186: a missing sample is not a neutral
# one).
