def _thin_tip(rows: list, k: int, key=None) -> list:
    """Keep *k* of a tip table's interior rows — **the ones a chord misses**.

    Not evenly spaced, and that is a measured difference rather than a
    preference: a fingertip's curvature is all at the end, so even spacing puts
    rings where the curve is already straight.  Greatest deviation from the
    measured curve over the five digits, at this figure's stature:

    ======  ==============  ========
    rings   evenly spaced   this
    ======  ==============  ========
    1       0.98 mm         1.14 mm
    2       0.98 mm         0.42 mm
    3       0.65 mm         **0.15 mm**
    4       0.42 mm         0.09 mm
    5       0.15 mm         0.05 mm
    6       0.00 mm         0.00 mm
    ======  ==============  ========

    ``detail.n(4, 2)`` puts the shipping level (medium) on **three**: one ring
    more than the typed taper it replaces (+8 vertices a digit, +80 on the body)
    for a residual of 0.15 mm, against a body whose distance to Origin has a p50 of
    0.46 mm.  Low draws 2, high 4, ultra 5.  The price list is the same kind
    §7.222 and §7.236 asked for before buying resolution, and the same
    conclusion — buy the cheap part and stop: going from three rings to five
    costs 160 vertices and buys 0.10 mm, which is under this ruler's own noise
    floor (0.02 mm) but well under anything the body's own error can show, and
    N20 already has the hand at 34% of our vertices against Origin's 19.9%.

    The last interior row always stays: it is where the closing cone starts, so
    dropping it would move the apex's base off the last thing measured.

    *key* maps a row to the ``(fraction, radius)`` pair the chord is drawn
    through, with the radius as a fraction of the section the tip grows out of.
    The default reads a :data:`DIGIT_TIP` row; :data:`FOOT_TIP` passes its own
    because its rows carry two profiles as well, and the two tips are thinned by
    this one function rather than by two copies of it.
    """
    key = key or (lambda r: (r[0], r[1]))
    inner = [r for r in rows if key(r)[0] < 1.0]
    if k >= len(inner):
        return inner
    keep = [len(inner) - 1]
    while len(keep) < max(k, 1):
        ix = sorted(keep)
        # the chord as drawn: the t=1.0 section (f=0, r=1) through the kept rows
        # to the apex (f=1, r=0)
        fs = [0.0] + [key(inner[i])[0] for i in ix] + [1.0]
        rs = [1.0] + [key(inner[i])[1] for i in ix] + [0.0]
        worst, pick = -1.0, None
        for j in range(len(inner) - 1):
            if j in keep:
                continue
            err = abs(float(np.interp(key(inner[j])[0], fs, rs))
                      - key(inner[j])[1])
            if err > worst:
                worst, pick = err, j
        if pick is None:
            break
        keep.append(pick)
    return [inner[i] for i in sorted(keep)]


def _loft_ring_ids(base: int, sides: int, count: int, j: int) -> list:
    """Which vertices ring *j* of a :func:`primitives.loft` became.

    The loft transposes its grid (vertex ``i * count + j``), and a fork needs
    the ids rather than the points — :func:`primitives.fork_faces` joins
    vertices that already exist, which is what carries the UVs, weights and
    labels across the join for nothing.
    """
    return [base + i * count + (j % count) for i in range(sides)]


def build_hand(p: dict, skel: Skeleton, prop: Proportions, side: str,
               record: dict | None = None, forks=None) -> Mesh:
    """The hand — palm, five digits, and the fork chain past the knuckle.

    *forks* is :data:`PALM_FORK_TRUNK` and exists so the state before it stays
    **measurable**: an empty list gives the capped palm, five tubes from their own
    t = 0 and the three web tubes back, which is what every reading recorded
    before §7.300 was taken on.  ``CLAUDE.md`` 七's rule — a candidate that has
    been decided still has to be askable, or the numbers behind the decision stop
    being reproducible (§7.278 added ``--branch chain=bone`` for the same reason,
    and §7.233 is why: re-measure the old rather than quoting it).
    """
    from .skeleton import FINGERS
    forks = PALM_FORK_TRUNK if forks is None else list(forks)
    hs = mul(p, "body.hand_size", 0.80, 1.22)
    wrist = skel.world_position(f"cf_j_hand_{side}")
    roots = [skel.world_position(f"cf_j_{f}01_{side}") for f, _ in FINGERS]
    palm_end = np.mean([r for r, (f, _) in zip(roots, FINGERS) if f != "thumb"], axis=0)

    root_map = {f: skel.world_position(f"cf_j_{f}01_{side}") for f, _ in FINGERS}
    # local frame: forward along the palm, across the knuckles, up off the back
    fwd = m3.normalize(palm_end - wrist)
    across = m3.normalize(root_map["little"] - root_map["index"])
    across = m3.normalize(across - fwd * float(np.dot(across, fwd)))
    up = m3.normalize(np.cross(fwd, across))
    if side == "R":
        up = -up

    out = Mesh(f"hand_{side}")

    # ---- palm: :data:`PALM_SECTIONS` swept along :data:`LIMB_AXIS` ---------
    # One tube, not a loft plus four knuckle balls plus a web ball.  The pile of
    # primitives was visible to the ruler before it was visible on screen: a
    # plane through our palm cut **2 to 7 loops** where Origin's cuts one, which is
    # what "a section of two things is not a section" looks like from inside our
    # own mesh (§7.200).  The knuckles come out of ``PALM_OUTLINE`` — they are
    # the 1.19–1.25 rays at 150–165° from t = 0.625 on.
    #
    # **And the thenar comes out of this tube now, not out of the thumb's**
    # (§7.288).  Out to :data:`PALM_FUSED_TIP` the reference's own section is a
    # single closed curve round palm and thumb, so these two tables describe
    # that curve and this sweep draws it; the thumb's tube and the thumb-index
    # bridge are then inside it rather than beside it.  What that is worth is
    # measured on the ruler that found it: our own section stops holding the
    # thumb at t = 0.6886 against Origin's 0.7741, where it used to give up at
    # 0.1210 — **38.3 mm early down to 4.8** — and this piece's share of normals
    # more than 30° out went 16.0% → **6.2%** with its median distance 1.32 →
    # 1.16 mm.
    # The ring is built in :func:`_measured_frames`' frame (``frames=`` below),
    # so there is no hint to get right any more.  What that replaced is worth
    # keeping as the tell: ``up_hint`` had to be ``across`` and not ``up``,
    # because ``tube_along`` puts the radius on ``frames_along``'s ``nor`` while
    # the table's ``r1`` is measured along ``_limb_frame``'s ``e1`` — hinting
    # with the palm's own normal built the table sideways (r1 **−59%**, r2
    # **+104%**, a palm rotated a quarter turn; the calf's failure in §7.169 and
    # the same tell — the two semi-axes swap and nothing else moves).  ``across``
    # was the right *approximation* and still 8.2° off (§7.291).
    pp, pr, psq, pratio, paxis = palm_profile(p, skel, prop, side)
    # **The palm's first ring has to finish inside the forearm.**  It is backed
    # off the wrist joint already (:data:`PALM_BACK`), but backing a ring into a
    # tube does not put it *inside* one: measured, the palm's first radius is
    # **26.29 mm** where the arm's last is **24.73** at the same station, so
    # 1.6 mm of that cap stood proud all the way round — 22 of its 25 vertices
    # visible, **100% of their normals more than 30° out**.  That rim is N13's
    # wrist step, and it is the same rule the leg's top ring and the trunk's
    # base ring already follow: a cap is only allowed where nothing can see it
    # (§7.230).
    #
    # Clamped to the arm's **own** sweep rather than to a typed number, so it
    # follows the arm sliders; the margin is ``_contain_in_trunk``'s, and it
    # only has to exceed the two surfaces' own sampling.
    #
    # **Against the arm's ring, not against its radius** (§7.289).  The scalar
    # form of this clamp compared ``pr[0]`` with ``ar[j]`` and so agreed with
    # the arm about exactly one direction: measured, it pulled 21 of the 24
    # rays in by up to 4.81 mm more than they had to come — the wrist row is a
    # measurement (§7.285 took it from the ``hand`` ∪ ``arm`` union) and this
    # was throwing 11% of it away — and it still let **three** rays out, by
    # 0.82 mm, which is a rim right round the cap it exists to bury.  An arm
    # section has a squash and a 24-ray outline ratio; one number cannot hold
    # either.  Applied through ``ratio`` because that is the per-vertex knob
    # ``tube_along`` already has, so the ring keeps its measured shape
    # everywhere it was already inside.
    _ap, ar, asq, ara, aax = arm_profile(p, skel, prop, side)
    ap = np.asarray(_ap, dtype=np.float64)
    c0 = np.asarray(pp[0], dtype=np.float64)
    j = int(np.argmin(((ap - c0) ** 2).sum(axis=1)))
    # Both rings come off the recipe the sweeps themselves use, so this is the
    # geometry that will be built and not a second spelling of it.  A transport
    # frame only re-parameterises a ring — the outline sampler reads the
    # measured frame — so neither ring's *shape* depends on where its sweep
    # started, which is what lets the arm's be asked here without the stub rows
    # ``_reach_into_trunk`` prepends in ``build_body_mesh``.
    pr = np.asarray(pr, dtype=np.float64)
    host = prim.sweep_rings(ap, ar, limb_sides(), squash=asq, ratio=ara,
                            frame_pts=aax,
                            frames=getattr(ara, "frames", None))[j]
    ring0 = prim.sweep_rings(pp, pr, limb_sides(), squash=psq,
                             ratio=pratio, frame_pts=paxis,
                             frames=getattr(pratio, "frames", None))[0]
    fit = _fit_inside_ring(c0, ring0 - c0, host, ap[j], 0.002 * prop.height)
    base_ratio = pratio

    def pratio(i, offs):                                # noqa: F811
        r = np.asarray(base_ratio(i, offs), dtype=np.float64)
        return r * fit if int(round(float(i))) == 0 else r
    # ``limb_sides()``, not a count of its own: the palm reads
    # :data:`PALM_OUTLINE`, which is :data:`LIMB_RAYS` rays wide like every
    # other outline table, so its ring has to be a multiple of that or half of
    # each station's measured shape is interpolated away (§7.222 measured what
    # that costs on the thigh's apex: 8.97 mm against 2.91).  It was
    # ``detail.even(24, 12)`` = **20** at the shipping detail level — not a
    # multiple, and the one ring on this body still reading a table on a grid of
    # its own.
    # **Open at the knuckle line, because the fork chain closes it** (§7.300).
    # The distal cap was the plate: 25 vertices, 24 of them visible, 100% of
    # their normals more than 30° off Origin's and a median of 77.8°, with four tubes
    # crossing it (§7.283/§7.288/§7.297).  §7.283 proved a triangulation cannot
    # buy that back — the hub's outline holds nine closed loops, so the surface
    # would still be a plane and a plane's normals are the plane's — and
    # :data:`PALM_FORK_TRUNK` is the other half it asked for: topology *and*
    # shape, the trunk carrying on past the knuckle and shedding one digit at a
    # time the way Origin's own section does.
    palm = prim.tube_along(pp, pr, limb_sides(), "palm", squash=psq,
                           caps=(True, not forks), ratio=pratio,
                           frame_pts=paxis,
                           frames=getattr(base_ratio, "frames", None))
    out.append(palm)
    # A ``loft`` lays its grid out as ``(sides, rings)`` before either cap, so a
    # named ring's vertices are an arithmetic slice of it.  Asked here rather
    # than searched for by position later: two vertices of a fork have to be
    # *the same* vertex as the trunk's, or the shading breaks along the seam
    # exactly the way N25 (c)'s intersections do.
    mother = _loft_ring_ids(0, limb_sides(), len(pp), -1)

    # ---- fingers with joint swell and nails -------------------------------
    nail_col = col(p, "body.nail_color", (0.98, 0.86, 0.86))
    # Fingers are scaled by stature and the hand slider, which is what moves
    # their bones too (``BIND_REF["hand"] × height × hand_size``), so the skin
    # and the chain stay the same size as each other.
    unit = prop.height * hs
    # **Where each digit's own tube starts** (§7.300).  A fork hands everything
    # distal of it to the branch's own table and everything proximal to the
    # trunk's ring, so a forked digit begins part-way along itself: §7.295's
    # ``own t``, 0.24-0.36 for the three that leave and 0.199 for the middle,
    # which is where the trunk stops being the palm and becomes that finger.  The
    # thumb is not in the chain — its fork is ruled out on two independent counts
    # (§7.295: the plane meets its chain at 0.836, and 24 rays put one vertex on
    # it) — so it still runs from its own t = 0 with its base cap inside the
    # palm's fused section.
    start_t = {r["leaves"]: r["own"] for r in forks}
    if forks:
        start_t[forks[-1]["digits"]] = forks[-1]["host"]
    first_ring: dict = {}
    for fname, segs in FINGERS:
        chain = np.array([skel.world_position(f"cf_j_{fname}{i + 1:02d}_{side}")
                          for i in range(segs)])
        tip_dir = (m3.normalize(chain[-1] - chain[-2]) if segs > 1
                   else m3.normalize(chain[-1] - root_map[fname] + fwd * 1e-3))
        n = detail.n(16, 10)
        # **Uniform, and that is measured** (§7.266).  ``DIGIT_SECTIONS`` has
        # 12-13 stations against the sweep's 12 samples, so §7.220's rule (take
        # the table's own stations too) reads as due here the way it was on the
        # palm; measured, it costs **+928 vertices** — a digit's rings are
        # 8-sided, so a station buys 80 of them across ten fingers — and the
        # folds get *sharper*, 27.8% of the hand's edges over 25° against
        # 30.7% and the 10th-percentile turning radius 3.55 mm against 3.17.
        # Near-equal grids interleave into pairs of close rings, which is the
        # opposite of resolving a table.
        t = np.linspace(start_t.get(fname, 0.0), 1, n)
        # **A forked digit starts one of its own cells in** (§7.308), so the
        # strip :func:`primitives.fork_faces` draws spans an interval instead of
        # standing in for none of one.  Same knob and same unit as the foot's
        # (§7.307) — here a cell is one interval of this grid.  Only the forked
        # four: the thumb runs from its own t = 0 and has no strip.
        if fname in start_t:
            t = fork_span_grid(t)
        # **By arc length along the bone polyline**, which is what
        # ``limb_profile`` walks — not a Catmull-Rom parameter, and not over a
        # chain with the fingertip already spliced onto the end.  A digit's two
        # phalanges are not the same length, so a uniform spline parameter is
        # not the table's ``t``, and the extension made it a third one: at
        # t = 0.92 of the bone chain our index finger was drawing the table's
        # t = 0.61 (§7.200).  A finger in the bind pose is straight to within a
        # degree, so nothing is lost by sampling the polyline itself.
        cp = _arc_points(chain, t)
        base, squash, o1, o2 = _limb_sections(DIGIT_SECTIONS[fname], t, 1.0)
        radii = base * unit
        # **The tip, from :data:`DIGIT_TIP`.**  The chain ends inside the
        # fingertip, so the tube has to carry on past it, and until §7.244 that
        # stretch had no ruler: it was two typed samples (``× 0.82`` at 0.55 of
        # the reach, ``× 0.30`` at the end) and a flat fan disc — a cone where
        # Origin has a dome, and the hand's worst row on every column (66-89% of
        # those normals more than 30° out).  ``--tip`` measures it now, so the
        # rings are the table's and the disc is gone: the fan closes onto the
        # **point the surface reaches**, which is what ``end_apex`` is for.
        #
        # Appended before ``_limb_offset`` rather than after, so the tip's own
        # measured drift (``o2``, up to −0.17 of the reach on the middle finger)
        # goes through the same frame as the shaft's instead of a second copy of
        # that arithmetic.  ``o2`` is in units of the reach, so it converts by
        # ``DIGIT_REACH`` and is relative to the t = 1.0 station, which already
        # carries the shaft's own offset.
        reach_f = DIGIT_REACH[fname]
        tip_rows = _thin_tip(DIGIT_TIP[fname], detail.n(4, 2))
        cp = np.vstack([cp] + [cp[-1] + tip_dir * (reach_f * unit) * r[0]
                               for r in tip_rows])
        radii = np.concatenate([radii, radii[-1] * np.array(
            [r[1] for r in tip_rows])])
        squash = np.concatenate([squash, np.array(
            [squash[-1] * r[2] / max(r[1], 1e-9) for r in tip_rows])])
        o1 = np.concatenate([o1, np.full(len(tip_rows), o1[-1])])
        o2 = np.concatenate([o2, np.array(
            [o2[-1] + (r[3] if r[3] is not None else 0.0) * reach_f
             for r in tip_rows])])
        # **``up_hint``, not the table's own frame — and that is measured**
        # (§7.292).  Every other sweep on this body was moved onto
        # :func:`_measured_frames` in §7.291/§7.292, and the five digits were
        # tried and **rejected**: the transported frame sits **8.0-16.3°** off
        # the frame ``r1``/``r2`` are stored in (the thumb is the worst), so
        # turning the ring onto the table's own rays reads as plainly due — and
        # the picture threw it out.  With it, the hand's 45° silhouette against
        # ``--origin-mesh`` went IoU 0.9761 → **0.9687** and ``ours only`` 1,438 →
        # **2,240 px**, all of it the thumb; taking it back off reproduced the
        # old figures column for column.
        #
        # The reason is in the table, not in the frame: :data:`DIGIT_SECTIONS`'
        # thumb withholds ``o1``/``o2`` on its **first eight stations**
        # (0.0417‥0.6250, two thirds of the chain) because the ring does not
        # close there — and stores ``r1``/``r2`` all the same.  An open arc's
        # ``r1``/``r2`` are its **bounding box**, not an ellipse's two
        # semi-axes, so the stored squash (0.265 on the index's root station,
        # 1.762 on the thumb's) is not a shape.  Putting a bounding box on the
        # right bearing only makes a wrong shape more definite.  §7.176's rule
        # — a station that could not be measured has to be marked, and both the
        # generator and the ruler read the mark — has never reached these five.
        cp = _limb_offset(cp, o1, o2, side, unit)
        apex = cp[-1] + tip_dir * (reach_f * unit) * (1.0 - tip_rows[-1][0])
        # A forked digit's base is **open**: the fork's own strip closes it onto
        # the trunk, and a cap there would be a second surface across the same
        # ring (§7.230's rule read the other way — a cap is only allowed where
        # nothing can see it, and here nothing needs one).
        forked = fname in start_t
        sides_f = detail.even(9, 6)
        fm = prim.tube_along(cp, radii, sides_f, fname,
                             squash=squash, caps=(not forked, True),
                             up_hint=across, end_apex=apex)
        if forked:
            first_ring[fname] = _loft_ring_ids(out.vertex_count, sides_f,
                                               len(cp), 0)
        out.append(fm)

        # The nail is **seated on the section**, not placed at a typed height.
        # Origin has no nail geometry at all — its nails are the B channel of the
        # body's ``_ColorMask``, painted on (§7.144) — so whether we carry any
        # is a product decision (§7.135) and its proportions are ours.  Where
        # it *sits* is not: anchored to a constant 0.0070 × unit while the
        # fingertip's own measured radius is 0.0031 of stature, it floated
        # clear of the finger and was the whole of the +40% our last station
        # measured against Origin's (a second loop in the cut, 2 mm of daylight
        # under it).  Every dimension below is a fraction of the section the
        # tube actually draws there, so it cannot come adrift again.
        # Counted from the **shaft's** stations, not back from the end of the
        # array.  It was ``len(cp) - 4``, which meant "two stations before the
        # last table row" only for as long as the tip was exactly two samples
        # long; §7.244 made the tip a table, and an index that has to know how
        # many rings the tip drew is an index that moves when the detail level
        # does.
        # ``len(t)`` and not ``n``, so that this index does not have to know
        # how the shaft was sampled — the same reason it stopped counting back
        # from the end of the array when §7.244 made the tip a table.
        k = max(len(t) - 2, 0)
        r_k = float(radii[k])
        # The semi-axis on ``bi``, which is the section's half-extent along
        # ``up`` **because the ring is built in the transported frame** — the
        # two are the same number only while ``bi`` is ``up``, and hinting with
        # ``across`` is what makes it so.  If these tubes ever move onto
        # :func:`_measured_frames` (see above for why they have not), this has
        # to become the ellipse's radius along ``up``, or the nail comes adrift
        # again (§7.230).  §7.292 wrote that version and measured it: the seat
        # moves **±0.01 mm** on all five digits, so the two forms are
        # interchangeable in size and not in provenance.
        d_k = r_k * float(squash[k])
        nail = prim.ellipsoid(0.62 * r_k, 0.22 * d_k, 1.15 * r_k,
                              detail.even(10, 6), detail.n(6, 4), "nail")
        nrm = m3.normalize(apex - cp[k])
        nail.transform(m3.quat_to_mat4(
            m3.quat_from_to(np.array([0.0, 0.0, 1.0]), nrm)))
        nail.translate(cp[k] + up * (d_k - 0.30 * d_k * 0.22))
        nail.set_color((*nail_col, 1.0))
        # Which vertices these are, so a ruler can leave them out.  Origin has no
        # nail geometry, so every millimetre and every degree measured on them
        # is measured against a finger — and it is not a small share: they are
        # 41–57% out of true and about **22% of the hand's bad vertices**
        # (§7.230).  A ruler that scores a part the reference does not have is
        # the third of this family (§7.187 scored images nothing drew, §7.227
        # scored vertices nobody can see).
        if record is not None:
            n0 = out.vertex_count
            out.append(nail)
            record.setdefault("nail", []).extend(range(n0, out.vertex_count))
            continue
        out.append(nail)

    # ---- the fork chain, from :data:`PALM_FORK_TRUNK` ---------------------
    # The trunk carries on past the knuckle and sheds a digit at each measured
    # fork; the last one hands it to the middle finger.  Each fork's strips are
    # built between vertices that **already exist** (``weld``'s rule), so the
    # trunk, its three runs and the four digits are one surface with one set of
    # normals across every join — which is the half of N25 (c) a cap and four
    # crossing tubes could not have.
    #
    # A refusal is **reported, not patched** (一之一): :func:`primitives.
    # fork_faces` answers 0 when the mother's vertices do not fall into two
    # contiguous arcs, and a fork that did not build would leave the trunk open,
    # so it goes in ``record`` for the caller to put in ``absent``.
    for run in forks:
        leaves = first_ring.get(run["leaves"])
        if run["sections"]:
            rpts, rrad, rsq, rratio, raxis = trunk_run_profile(
                p, skel, prop, side, run)
            host = _loft_ring_ids(out.vertex_count, limb_sides(),
                                  len(rpts), 0)
            nxt = _loft_ring_ids(out.vertex_count, limb_sides(),
                                 len(rpts), -1)
            out.append(prim.tube_along(
                rpts, rrad, limb_sides(), f"trunk_{run['leaves']}",
                squash=rsq, caps=False, ratio=rratio, frame_pts=raxis,
                frames=getattr(rratio, "frames", None)))
        else:
            host = first_ring.get(run["digits"])
            nxt = None
        if leaves is None or host is None:
            if record is not None:
                record.setdefault("fork_absent", []).append(run["leaves"])
            continue
        info: dict = {}
        added, why = prim.fork_faces(out, mother, leaves, host, info=info)
        if why and record is not None:
            record.setdefault("fork_refused" if not added else "fork_warn",
                              []).append(
                f"{run['leaves']} ({why}; arcs "
                f"{info.get('arc_a')}/{info.get('arc_b')})")
        mother = nxt if nxt is not None else mother

    # ---- the interdigital webs, from :data:`HAND_WEB` ---------------------
    # The fork.  Tubes leaving a capped palm separate the moment their own
    # chains do, and Origin's do not: measured perpendicular to this axis, its index
    # and middle share one closed curve until 0.157 of the palm axis past the
    # knuckle where ours part at 0.009 — **9.1 mm** of fused skin missing, on
    # two of the three pairs, with the third (ring-little) not fused at all
    # (§7.252).
    #
    # Built as a swept ring about the line between the two digit axes rather
    # than as a membrane between the two tubes, for the reason every other
    # junction on this body is a union: a sheet has no thickness and this one is
    # 9–11 mm thick where it leaves the palm.  Its across-radius reaches exactly
    # the two axes, so its extremes are **inside** both finger tubes and the
    # union is what shows; the ring's depth is the measurement.
    #
    # This is not the branching hub §7.250 called for — the palm's own opening
    # is still a cap and the fingers still cross it — but the surface it puts
    # between the fingers is measured rather than absent.
    # **A pair the palm's own sweep already bridges needs no tube** (§7.288).
    # ``PALM_SECTIONS`` describes the section the thumb is still *in* out to
    # :data:`PALM_FUSED_TIP`, so the whole of the thumb-index bridge — its
    # crotch is at t = 0.7597, proximal of that — is drawn by the palm tube
    # itself now, and a second tube over the same skin is not a union, it is
    # 1.1-1.9 mm of extra flesh (``--fork``'s ours-minus-Origin column measured it).
    # The other three crotches are at 0.97-1.16, past everything any ring on
    # this axis can carry (§7.284: from 1.0045 the section is no longer one
    # closed curve), so those three stay.
    #
    # Data-driven rather than a name: the criterion is the pair's **own**
    # measured crotch against the station the fused section stops at, both of
    # them from the same ruler.
    hand_len = float(np.linalg.norm(root_map["middle"] - wrist))
    a_hat = m3.normalize(root_map["middle"] - wrist)
    # ``_limb_offset``'s recipe, and it is load-bearing: ``off``'s sign lives in
    # a quarter turn of :func:`_limb_frame`, and a cross product is not
    # preserved by a reflection.  Measured on Origin before the mirror went in, the
    # two hands reported ``off`` −0.0033 and +0.0033 — an apparent L-R spread of
    # 0.0066 on a column whose whole range is 0.0014.
    mir = np.array([-1.0, 1.0, 1.0]) if side == "R" else np.ones(3)
    for key, rows in HAND_WEB.items():
        # **The criterion is the fork chain's reach now, not the thumb's**
        # (§7.300).  §7.288 skipped a pair whose crotch the palm's own fused
        # section already covered; the trunk's runs now cover every one of the
        # four, so all four are skipped and the rows stay as the measurement the
        # skip is decided on — the same argument written above for the
        # thumb-index rows, generalised.  If a re-measure ever moves a crotch
        # past :data:`PALM_FORK_TIP`, this loop builds that pair again.
        if rows[-1][0] <= (PALM_FORK_TIP if forks else PALM_FUSED_TIP):
            continue
        na, nb = key.split("-")
        chain_a = np.array([skel.world_position(f"cf_j_{na}0{i}_{side}")
                            for i in (1, 2, 3)])
        chain_b = np.array([skel.world_position(f"cf_j_{nb}0{i}_{side}")
                            for i in (1, 2, 3)])
        pts, radii, squash, frames, ts = [], [], [], [], []
        for t_w, half, off in rows:
            s_w = (t_w - 1.0) * hand_len
            pa = _axis_station(chain_a, root_map["middle"], a_hat, s_w)
            pb = _axis_station(chain_b, root_map["middle"], a_hat, s_w)
            d = pb - pa
            d = d - a_hat * float(d @ a_hat)
            g = float(np.linalg.norm(d))
            if g < 1e-9:
                continue
            u_w = d / g
            v_w = np.cross(a_hat * mir, u_w * mir) * mir
            r1 = 0.5 * g
            # ``unit``, i.e. stature × ``hand_size``, like the palm and the
            # digits — the slider scales the bones, so a thickness taken off
            # stature alone would stay put while the fingers it bridges moved
            # apart.  The across-radius needs no factor: it is the distance
            # between two of the armature's own joints and already carries it.
            pts.append(0.5 * (pa + pb) + v_w * (off * unit))
            radii.append(r1)
            squash.append(half * unit / r1)
            # **This pair's own frame, per station** (§7.292).  ``u_w`` is what
            # ``r1`` is measured along and ``v_w`` what ``half`` is, so they are
            # this table's frame in the same sense :func:`_measured_frames` is
            # the others' — and unlike those two, they are already in hand here.
            # It used to hint ``frames_along`` with the **first** station's
            # ``u_w`` and transport from there; measured, that leaves the ring
            # 0.9° off on index-middle, **9.3°** on middle-ring and
            # **14.3-15.3°** on ring-little, and a web is the flattest section
            # on this hand (its squash is a thickness over a half-span), so the
            # angle is most of what it costs.  Part of it is not even drift: a
            # hint that is not perpendicular to the centreline's own tangent is
            # projected, and the ring is turned before the first step.
            frames.append([u_w, v_w])
            ts.append(t_w)
        if len(pts) < 2:
            continue
        # :data:`WEB_OUTLINE` in the frame it was measured in, which is the one
        # already collected above — so the sampler needs no ``_measured_frames``
        # and no interpolation in ``t``: the two tables have the same stations
        # by construction, one station per ring.  Subscripted and not ``.get``:
        # a pair with a thickness and no shape is the two tables out of step,
        # which is an error to report rather than an ellipse to fall back to
        # (一之一 — and the fallback would be invisible, since an ellipse is
        # exactly what this used to draw).
        out.append(prim.tube_along(np.array(pts), np.array(radii),
                                   WEB_SIDES, f"web_{na}_{nb}",
                                   squash=np.array(squash), caps=True,
                                   frames=np.array(frames),
                                   ratio=_web_sampler(WEB_OUTLINE[key],
                                                      frames, ts)))

    out.compute_normals()
    return out


# --------------------------------------------------------------------------
# The foot, sliced off ``o_body_a`` with the plane z = const rather than binned
# off its vertices: the foot carries 466 of them, so a station holds ~30 and an
# across-band inside it holds one or none — the binned version sawtoothed
# between the sole and the instep and would have been ported as shape.
#
# Re-measured with ``python tools/body_profile.py --foot --emit`` (§7.225, again
# in §7.245), on the **shaped** armature like every other table since §7.175.
# The generating script used to be missing — ``--digits foot`` is a different
# ruler, it answers "how many separate lobes does this foot cut" — and what that
# cost is written up in §7.225.
#
# Each row is ``(dz from the ankle bone, half-width, centre offset, sole,
# (upper profile at 13 samples across))``, all fractions of stature, with the
# ground at y = 0.  **Where those thirteen samples are is
# :func:`foot_across_u`, and they are not evenly spaced** — re-measured on that
# grid in §7.296, which is also where the price list for the count lives.  The
# upper profile is what carries the toes: Origin's are
# **fused ridges**, not five tubes — the notches between them are 0.0017–0.0025
# of stature (3–4 mm on this figure), which is why a "count the separate pieces"
# ruler answered *2* about a foot that has five (§7.169).
#
# 68 of the 176 interior samples are the station's own greatest height rather
# than a slice: behind the ankle the top of the section is the **leg's**
# surface, so the foot segment has no top there.  Those rows come out flat and
# the leg tube plugs into them.
#
# What it replaced was seven typed rings and a sphere for the ankle, and the
# sphere is why the foot measured 69% too tall: it reached 0.060 of stature
# where Origin's whole foot stops at 0.0416.  Ours also came out 28% too long and
# 34% too wide, and stood 23 mm **above** the floor.
