# **How the foot closes past the outermost station**, from ``--foot --tip``.
#
# The stations above are cell centres, so each end of the table stops half a
# spacing (5.67 mm here) short of the surface — the same shape of error §7.209
# found on every other table on this body.  What used to fill the two half-cells
# was typed: the outermost section *scaled by 0.30*, then a fan cap on its
# centroid.  Measured, that was the foot's worst row — the toe cap ran **68%**
# of its normals more than 30° from Origin's at 2.88 mm, and the stations either
# side of it 41-92% (§7.244).
#
# Rows are ``(f of the stub, dz, half_width, centre_offset, lower[13],
# upper[13])`` — the same units and the same two profiles as ``FOOT_SECTIONS``,
# so ``ring`` reads them like any other station.  ``f`` leads because that is
# what ``_thin_tip`` picks by, and both tips of this body are thinned by that
# one function.
#
# Two things the typed rings could not do, and both are why they were the worst
# row:
#
#   * The half-width does not taper.  Origin holds it to within 8% out to 0.60 of
