# How many of the six measured rows each end draws — ``detail.n`` scales it, so
# the shipping level (medium) gets 3, low 2, high 4, ultra 5.
#
# The price list is the one §7.222/§7.236/§7.244 asked for before buying
# resolution, and it is measured with ``--gaps`` restricted to the two stubs.
# ``--vs-shape`` is the wrong column here and that is worth writing down: it
# walks **our** vertices to Origin's surface, and a vertex sitting on a measured
# station is on that surface however few of them there are — it reads 0.03-0.04
# mm for every row below.  What a ring buys is the surface *between* stations,
# and only Origin's skin walking to ours can see it.  Restricted to the stubs, too:
# they are 5.66 mm of a 181 mm foot, so over all 932 of Origin's foot vertices the
# whole question moves the p50 by 0.08 mm.
#
#   ===== ============ ================= =================
#   rings extra verts  heel p50 / p90    toe p50 / p90
#   ===== ============ ================= =================
#   typed 0            1.241 / 2.710 mm  0.875 / 2.558 mm
#   2     +128         0.779 / 2.181     0.390 / 1.094
#   **3** **+192**     **0.532 / 2.181** **0.449 / 1.084**
#   4     +256         0.455 / 2.181     0.413 / 1.084
#   5     +320         0.424 / 0.542     0.321 / 0.751
#   ===== ============ ================= =================
#
# Three.  Replacing the typed ring is the whole of the cheap part — it halves
# both stubs — and after that the p50 crawls; the toe's is not even monotone
# (42 vertices), so 2 against 4 there is this ruler's noise.  Five is where the
# p90 collapses, and it costs 192 vertices more on a part already carrying 964
# against Origin's 932 (N20), for 0.1 mm of p50.  Bought the cheap part and stopped.
FOOT_END_RINGS_BASE = 4

# The point each end **reaches**, as ``(dz, centre_offset, height)`` of stature.
# Both are single vertices on Origin's foot, which is a measurement of where the
# surface stops (the same fact the old ``FOOT_ENDS`` pair reported, and it read
# the same two extremes) and not a copy of its shape.  The heel's is almost on
# the centre line; the toe's is 8.9 mm off it, because it is the big toe.
