# --------------------------------------------------------------------------
# The five toes, and the four forks that shed them.  Measured with
#
#   python tools/body_profile.py --foot --toes --emit
#
# **A foot is one skin and it sheds one toe at a time**, exactly as the palm
# sheds one finger at a time (§7.284/§7.300).  ``--foot --toes`` bisects the
# station where each adjacent pair stops sharing a closed curve — a topological
# event, so no threshold (§7.220) — and the four it finds *are* the whole tree:
# the toes are ordered along x and never cross, so every lobe is a contiguous
# run of them and the partition at any cut is the ordered five split at each
# pair that has already parted.  A fork here is binary by construction rather
# than by choice, which is what lets :func:`primitives.fork_faces` draw all four.
#
# One block per stretch over which the cut is a single closed curve carrying
# the same toes, ``parent`` naming the run whose **last** ring the fork joins
# (0 is :data:`FOOT_SECTIONS`').  ``at`` is the fork's own bisected station.
# Rows sit 2% of the run inside each fork, because the section exactly at one is
# the degenerate cut where two lobes touch.  **A tip's distal row is inset by
# the same fraction and it is not the same thing**: there it is the anchor the
# cap hangs from, so taking it away leaves the big toe's last 9.4 mm without a
# ring (§7.310) — two reasons wearing one constant, and only one of them was
# ever measured.  ``--foot --toes`` prices the tip's own fraction now that the
# cone is inside the scoring window, and the answer is to leave it: over
# 0.005-0.15 the whole-run error moves 0.1 mm about the shipped value and the
# best fraction is a different one on each of the five toes, which is what a
# sampling artefact looks like rather than a number (§7.311).
#
# A tip carries an ``apex`` instead of a station — the point that toe reaches,
# which is :func:`primitives._fan_cap`'s cone and not a flat disc (§7.244
# measured what a disc costs at 66-89% of its normals).  **Its z is the lobe's
# own vanishing point**, bisected like every fork here; §7.245's recipe
# averaged Origin's three highest vertices in all three coordinates, and a mean of
# samples stops short of the end by construction — 0.48 mm on the big toe,
# nearly three times the 0.17 mm cone it then had to close with.  x and y stay
# that three-vertex mean, and that split is measured and not tidy: the
# section's own centroid wins on the big toe (cap p50 0.50 → 0.11 mm) and loses
# on the other three, so only the coordinate that measures better moved
# (§7.311).
#
# **``form`` is measured, not typed.**  The two forms cost the **same
# twenty-four vertices** at the shipping counts — the graph over x draws 2n-2 of
# them at 13 samples and the ray ring draws 24 — so the choice is accuracy
# alone, and the tool scores both with one ruler at nine stations spread over
# each run (§7.263: two forms scored by one ruler can be read side by side;
# §7.302 first put them in one table).  What comes out is *not* "the trunk gets
# the graph and the branches get the rays":
#
#   ==== ============== ============== =======
#   run  cos p50/worst  ray p50/worst  ships
#   ==== ============== ============== =======
#   0    2.90 / 30.94   — (refuses)    cos
#   1    4.07 / 12.18   1.57 / 7.41    **ray**
#   2    3.17 / 6.06    4.60 / 6.73    cos
#   3    1.49 / 4.92    0.55 / 0.89    **ray**
#   4    3.39 / 9.99    1.09 / 1.83    **ray**
#   5    1.23 / 1.60    0.74 / 0.88    **ray**
#   6    1.33 / 5.14    0.71 / 0.87    **ray**
#   7    1.22 / 2.39    0.67 / 0.80    **ray**
#   8    1.26 / 3.83    0.42 / 0.94    **ray**
#   ==== ============== ============== =======
#
# in mm.  A toe is round, and a graph over x has a vertical tangent where its
# section closes, so the five branches go to rays by a factor of two to six.  A
# lobe carrying several toes has **notches** between them, which is a graph
# feature and not a star-shaped one (§7.190), and on run 0 the ray form does
# not merely score worse — it **refuses**, because the extent centre of a
# peanut sits in its own waist and every ray misses (§7.298 took that apart on
# the hand's index fork).  **Run 4 read as a refusal until §7.309** and was not
# one: that centre is a convention, and an interior one answers at 1.83 mm
# against the graph's 9.99.  Run 2 is the honest middle: 0.64 mm long, three
# toes, and both forms are 6 mm out on it.
#
# ``sections`` are ``(dz, r1, r2, cx, cy)`` in the ray form — half-extents on x
# and y, the centre's x from the ankle and its y **above the ground**, all
# fractions of stature, ground-relative like both of ``FOOT_SECTIONS``' profiles
# — and ``FOOT_SECTIONS``' own five columns in the cos form.  ``outline`` is the
# ratio table against that ellipse on 24 rays, the same form ``PALM_OUTLINE`` and
# ``LEG_OUTLINE`` store and read by the same :func:`_limb_outline_ratio`.
#
# **What it costs, against what Origin spends there** (N20, and §7.302's third
# constraint): the cascade is 36 rings and 5 tips past the first fork — **629
# vertices** at 24 a ring — against the **318** Origin spends past that same station
# on **one** foot, and it replaces 4 stations of ``FOOT_SECTIONS`` plus the toe
# stub's 3 rings and its cap.
#
# **That reads 1.98x, and it used to read "about even"** because the two sides
# counted different things: this table is one foot (the generator mirrors it)
# while Origin's ``foot`` segment is a whole body's, so the 636 it was held against
# is **two** (§7.333 三).  ``--foot --toes --emit`` prints both numbers now.
# So this *is* a finer grid than the reference's own sampling — which is the
# question §7.281 says to ask before buying resolution, and the answer it gives
# here is "not without selling something else", which is why §7.333 measured a
# placement that adds four rings and did not buy it.
#
# One table for both sexes, and that is measured: Origin's two bodies carry the same
# foot (932 vertices either way) and every fork station, toe length and price
# comes out identical on ``--sex 1`` (§7.302 六).
