# Where the sole sits **on the armature**, of stature.  The table above has its
# own ground at y = 0 and §7.169 put that on ``cf_j_root``, so our sole ended up
# on the floor — which reads as obviously right and is 14.54 mm below Origin's.
#
# Measured (§7.215): in Studio the character's root and ``cf_j_root`` are both at
# world **y = 0** and ``o_body_a``'s lowest vertex is at **+0.00850 of stature**,
# so Origin's own bind sole is 14.5 mm off the floor and the toe bones sit 26.6 mm up.
# On the shared armature (601 bones to 0.000 mm) our foot came out a **rigid**
# 14.54 mm low: its own height is 70.03 mm against Origin's 71.20, and Δmin −14.54 /
# Δmax −15.71 move together.  Everything on this body is authored against the
# bind, so a foot 14.5 mm below Origin's is 14.5 mm of error in every pose built on
# it — and it was the largest single number left on the body (§7.213 N22).
#
# Not scaled by ``foot_size``: this is where the body sits, not how big the foot
# is.  (Whoever plants the character adds the same 14.5 mm Origin's game does.)
# One owner: ``skeleton.SOLE_Y``.  The trunk's landmarks start at the same
# height for the same reason, and two copies of one constant is how a body
# ends up with its foot on Origin's sole and its torso on the root.
FOOT_SOLE_Y = SOLE_Y


def _foot_end_rows(end: str, k: int) -> list:
    """The *k* rows of one end's stub a chord misses, in **z order**.

    One place knows which station each stub grows out of, because that is what
    its half-widths are a fraction of and ``_thin_tip`` draws its chord from
    there to the apex.  The heel's rows run away from the table, so they come
    back reversed and the ring list stays monotonic along z.
    """
    hw0 = (FOOT_SECTIONS[0] if end == "heel" else FOOT_SECTIONS[-1])[1]
    rows = _thin_tip(FOOT_TIP[end], k, key=lambda r: (r[0], r[2] / hw0))
    return list(reversed(rows)) if end == "heel" else rows


def foot_across_u(n: int) -> np.ndarray:
    """Where :data:`FOOT_SECTIONS` samples across a section, ``-1`` to ``+1``.

    **Not evenly spaced, and that is measured** (§7.296).  A section closes at
    its own extreme x — the top profile turns through a right angle there and
    comes back as the sole — and an even grid gives that turn one cell, 17% of
    the half-width or about 5 mm on this foot.  ``--foot``'s price list reads
    the section itself at 401 positions and scores the polyline each candidate
    grid draws: the worst error sits at |u| ≥ 0.885 on **13 of the 16
    stations**, it does not move as the count goes up, and going 13 → 49 even
    samples (four times the vertices, on a part already carrying 1,156 against
    Origin's 932, N20) leaves it at 26.68 mm against 30.90.  It is where the
    samples are, not how many — the third time on this body (§7.222's rays,
    §7.291's frames).

    ``-cos(kπ/(n-1))`` gives the turn 3.4% of the half-width instead, which is
    0.6 mm.  It is the same rule every other section table here already samples
    by — uniform in angle round a circle (§7.208 put the torso's rings on it,
    §7.291 the limbs') — and the foot was the last one still on a grid uniform
    in a Cartesian coordinate.  Measured against the alternatives it is the one
    that can actually be built: placing the same thirteen where the error is
    reaches 5.69 mm against the even grid's 30.90, but it does it by crowding
    two samples **0.12 mm** apart on that corner and moving them 3.62 mm from
    one station to the next (9.84 worst) — a degenerate pair of rings and a
    skewed quad, which is §7.266's lesson from the other direction.  This one
    has no search in it, no station-to-station drift at all, and no constant to
    tune.

    One owner, and it is here: the ruler that emits the table reads this
    function, so the grid the numbers were measured on is the grid the ring is
    built on (§7.263 — a table checked on its own grid checks nothing, and that
    is exactly what ``--foot``'s ``top |d|`` column had been doing at 0.00 mm
    for every station since §7.225).
    """
    return -np.cos(np.linspace(0.0, np.pi, n))


def _foot_ring(hw: float, xc: float, lower, upper, z: float,
               sgn: float) -> np.ndarray:
    """One section: the upper profile left to right, then the **lower** back.

    *sgn* mirrors the whole thing for the right foot — the profile is the left
    foot's and the toes are not symmetric about the centre line, so a right foot
    built from it unmirrored has its big toe on the outside.

    The sole used to be a single scalar, so every section's bottom was a
    straight line across the foot's whole width.  A sole is not flat: measured
    against Origin's surface, ours sat **3.40 mm below it with coherence 0.77
    straight down** and 60.3% of its normals more than 30 deg out — the worst
    part of this body on every column of ``--vs-shape`` (§7.225).  Both
    profiles now come from the same cut (``--foot --emit``).

    There used to be a *shrink* here as well, scaling a section about its own
    mid-line to make the two terminal rings.  Nothing measured it and it is
    gone: the ends have their own measured stations now (:data:`FOOT_TIP`).
    """
    us = foot_across_u(len(upper))
    top = [(xc + sgn * u * hw, q, z) for u, q in zip(us, upper)]
    sole = [(xc + sgn * u * hw, q, z)
            for u, q in zip(us[-2:0:-1], list(lower)[-2:0:-1])]
    return np.array(top + sole, dtype=np.float64)


#: Segments round a **toe's** ring, before the multiple-of-rays rounding.
#:
#: :func:`limb_sides` rounds up from 24, which is right for a thigh and wrong
#: for a toe: it would put 32 vertices on a table 16 rays wide.  The number here
#: is the other half of :data:`FOOT_RUNS`' budget-neutral trade — 16 rays and
#: six placed rings against 24 rays and four even ones, the same 96 vertices a
#: toe, for 1.67 mm along it instead of 3.94 (§7.303).  *rays* is the table's
#: own width, not a global, for §7.236's reason.
FOOT_RUN_SIDES_BASE = 16


def foot_run_sides(rays: int) -> int:
    """:func:`limb_sides` for a foot run — same rounding, its own base."""
    n = int(rays) or LIMB_RAYS
    return int(math.ceil(detail.n(FOOT_RUN_SIDES_BASE, n) / n) * n)


def _foot_ray_ring(r1: float, r2: float, cx: float, cy: float, table,
                   dz: float, z: float, sgn: float, sides: int) -> np.ndarray:
    """One branch section: *sides* rays about the lobe's **own** centre.

    The second form a foot section takes, and which of the two each run ships
    is a measurement rather than a rule — see :data:`FOOT_RUNS`.

    Built here rather than through :func:`primitives.sweep_rings` because a
    foot's sections are planes of **constant z** and the frame they were
    measured in is the world's: ``r1`` lies on x and ``r2`` on y, so there is no
    chain to transport a frame along and no ``o1``/``o2`` to project into one
    (§7.291's three conditions are met by construction here, not by machinery).
    The mirror is :func:`_foot_ring`'s — ``sgn`` on x about the section's own
    centre, with the centre offset mirrored too, because the toes are not
    symmetric about the foot's centre line.

    Vertex *k* sits **on** ray *k* when *sides* is the table's own ray count,
    which is what :func:`limb_sides` rounds up to (§7.222).  The ratios come
    from :func:`_limb_outline_ratio` so that a station whose rays were withheld
    holds its neighbour's shape, exactly as every other outline table on this
    body does — one owner for "sample a ratio table".
    """
    # **Clockwise, because :func:`_foot_ring` is.**  The two forms sit in one
    # surface and a loft joins vertex *i* of one ring to vertex *i* of the next,
    # so every ring on this foot has to wind the same way — and the graph form
    # runs the upper profile left to right and the sole back, which is negative
    # area in (x, y).  Measured the direct way: with this ring counter-clockwise
    # all four forks came back "both windings clash (24 and 48 edges)" — the
    # strip agreeing with the mother then disagreeing with both children,
    # which is exactly the count §7.240's directed-edge test exists to report.
    th = -np.arange(sides) / sides * 2.0 * np.pi
    ratio = _limb_outline_ratio(table, dz, th)
    # The ellipse those ratios were measured against (``limb_ratios``).
    c, s = np.cos(th), np.sin(th)
    r = ratio * (r1 * r2) / np.sqrt(np.maximum((r2 * c) ** 2 + (r1 * s) ** 2,
                                               1e-18))
    return np.stack([cx + sgn * r * c, cy + r * s,
                     np.full(sides, z)], axis=1)


#: How far along its own run a fork's child draws its first ring, in the run's
#: **own** grid cells — so the fork's strip covers that first cell instead of
#: the 0.06-0.50 mm it used to (§7.307).
#:
#: One cell, and one cell is not a chosen length: the strip standing in for no
#: interval at all is what left it a fan of slivers whose normals are junk
#: (§7.304 localised the bad normals to exactly the first ring of every run,
#: 127-168 deg against 42-78 in the middle).  Giving it the run's own first
#: cell is the smallest interval the run itself names.  ``--forks --fork-span``
#: prices the alternatives in the same unit.
FORK_STRIP_STEPS = 1.0


def _row_lerp(a, b, f: float) -> tuple:
    """One station between two of a run's, component by component.

    A row is scalars and, for the across-form runs, two tuples of them
    (:data:`FOOT_SECTIONS`' upper and lower profiles), so this walks the shape
    rather than assuming it is flat.
    """
    out = []
    for x, y in zip(a, b):
        if isinstance(x, (tuple, list)):
            out.append(tuple(u + (v - u) * f for u, v in zip(x, y)))
        else:
            out.append(x + (y - x) * f)
    return tuple(out)


def fork_span_cut(n_rows: int):
    """Which of a child run's own cells the fork strip takes: ``(j, f)``.

    The child's first ring is drawn at row ``j + f`` of its own grid, so the
    strip covers that interval and the rows before it are gone.  ``None`` when
    there is nothing to give away — fewer than two rows, or the knob off.

    **One owner for the arithmetic**, because the two forks on this body state
    the rule in the same unit while holding their grids in different shapes: the
    foot's runs carry rows of the measured table (:func:`fork_run_rows`), the
    hand's digits carry a uniform sample grid over :data:`DIGIT_SECTIONS`
    (:func:`fork_span_grid`) and its trunk carries :data:`PALM_FORK_TRUNK`'s
    rows.  A cell is a cell in all three, and a rule fixed at one call site is a
    rule not fixed (七).

    A run of a single cell — three of the foot's eight are two stations long —
    cannot give the cell away and stay a tube, so the strip and the run **split
    it**, which is the only division that does not name a number.
    """
    t = float(FORK_STRIP_STEPS)
    if n_rows < 2 or t <= 0.0:
        return None
    t = min(t, n_rows - 2) if n_rows > 2 else min(t, 0.5)
    if t <= 0.0:
        return None
    j = int(math.floor(t + 1e-9))
    return j, t - j


def fork_span_grid(t: np.ndarray) -> np.ndarray:
    """:func:`fork_span_cut` on a sweep's sample parameters.

    The digits' form of it: their grid is uniform in ``t`` rather than a list of
    measured rows, so a cell is one sample interval and the head is a lerp
    between two of them.
    """
    t = np.asarray(t, dtype=np.float64)
    cut = fork_span_cut(len(t))
    if cut is None:
        return t
    j, f = cut
    head = t[j] if f <= 1e-9 else t[j] + (t[j + 1] - t[j]) * f
    return np.concatenate([[head], t[j + 1:]])


#: When a run that ends at a **fork** leaves a last cell shorter than this
#: fraction of the cell before it, that cell is a residual rather than a
#: station and the pair is merged.  ``0`` turns it off and reproduces the
#: construction that shipped up to §7.328, cell for cell.
#:
#: ``tools/body_profile.py --fork``'s ``edge`` insets a run's end rows off the
#: fork at each end, because the section exactly at a fork is the degenerate
#: cut where two lobes touch — and it states that inset as a fraction of the
#: **branch**.  What is left between the inset row and the scan station before
#: it is therefore not a length the run names: it is set by where the fork
#: happens to fall between two stations of a uniform grid.  On the two runs
#: :data:`PALM_FORK_TRUNK` ships it comes out **0.28 mm** and **0.43 mm**
#: against a preceding cell of 1.30 (0.22 and 0.33 of one), which is §7.266's
#: degenerate ring pair standing in the shipped mesh — and the same shape as
#: §7.310's ``EDGE = 0.02``, a proportion of the branch doing duty for a
#: property of the cell.
#:
#: Against the **preceding** cell rather than the run's median, because a run
#: of two cells has its median halfway between them: ``trunk_ring``'s residual
#: is 0.50 of that and 0.33 of the cell before it, so the median form would
#: put the shipped threshold on top of a coin flip.
#:
#: 0.5 is an interior point of a region and not an argmin (§7.315's shape):
#: the two runs flip at 0.22 and 0.33, so anything in (0.33, 1) drops both and
#: 1 would fire on any shortening at all.  Which value inside it is a
#: convention; that it is inside is measured.
FORK_ROW_MERGE = 0.5

#: Which row of a merged pair survives.  Both are rows the scan measured, so
#: neither choice invents a station and neither needs a re-emit (§7.328).
#:
#: They are not interchangeable.  The ``inset`` row is the mother ring the next
#: fork's strip is built on — :func:`build_hand` hands it to the following
#: :func:`primitives.fork_faces` — so keeping it leaves every fork exactly
#: where it is, and ``--forks`` reproduces ``turn``/``off``/``lane``/``span``
#: digit for digit under this merge.  ``"inner"`` keeps the scan station
#: instead, which walks the crotch chord 0.28/0.43 mm proximally: measured,
#: that is the direction §7.324's decomposition predicts (both children's
#: ``ax`` grows, both leans shrink) and hand fork #2's ``turn`` goes
#: 106.5 -> **113.8°** away from Origin's 52-91, its ``fold`` 123.0 -> 131.0, and
#: the side view's surface residual 933 -> 1094 px.  Kept reachable so that
#: negative result stays reproducible (§7.278).
FORK_ROW_KEEP = "inset"


def _fork_row_merge(rows: list, tip: bool) -> list:
    """:data:`FORK_ROW_MERGE` applied to one run's rows.

    Only where the run's distal end **is** a fork: a run ending at a tip
    carries its cone from that last row, and where that one sits was swept and
    bought separately (§7.315, ``EDGE_TIP`` = 0.08).
    """
    thr = float(FORK_ROW_MERGE)
    if tip or thr <= 0.0 or len(rows) < 3:
        return rows
    prev = float(rows[-2][0]) - float(rows[-3][0])
    last = float(rows[-1][0]) - float(rows[-2][0])
    if prev <= 0.0 or last >= thr * prev:
        return rows
    keep = str(FORK_ROW_KEEP)
    if keep == "inset":
        return rows[:-2] + rows[-1:]
    if keep == "inner":
        return rows[:-1]
    raise ValueError(f"FORK_ROW_KEEP: expected 'inset' or 'inner', "
                     f"got {keep!r}")


def fork_run_rows(run: dict) -> list:
    """A child run's stations, with its first ring :data:`FORK_STRIP_STEPS`
    cells along the run.

    The interval between a fork and its children's first rings belongs to
    somebody: before §7.307 the children started 0.06-0.50 mm past the mother's
    cut, so the strip :func:`primitives.fork_faces` draws is a fan of slivers
    and the run's own first ring carries the fold (§7.304/§7.305).  Handing the
    strip the run's **first cell** is the same surface described by the piece
    that spans it, and it is priced in the run's own grid so no length is
    invented.

    Both of the foot's children are runs of this shape; on the hand one child is
    a digit and the other is a stretch of :data:`PALM_FORK_TRUNK`, which is.
    **Both of a fork's children have to move or the strip still spans nothing on
    one side of it** (§7.308).

    The **distal** end is :data:`FORK_ROW_MERGE`'s.
    """
    rows = list(run.get("sections") or ())
    cut = fork_span_cut(len(rows))
    if cut is not None:
        j, f = cut
        head = rows[j] if f <= 1e-9 else _row_lerp(rows[j], rows[j + 1], f)
        rows = [head] + rows[j + 1:]
    return _fork_row_merge(rows, tip="apex" in run)


def build_foot(p: dict, skel: Skeleton, prop: Proportions, side: str,
               record: dict | None = None) -> Mesh:
    """The foot and its five toes — one surface, forked at four stations.

    The foot proper is :data:`FOOT_SECTIONS` as before, but it now **stops at
    the first fork** (§7.303).  Past there the cut is no longer one closed
    curve, so a station of it is a bound over the toes' union rather than a
    description of them (§7.190; ``--foot``'s ``loops`` column has printed
    2/5/4/3 across those stations since §7.245, and §7.296 measured that no
    across-grid, however fine, moves them).  What follows is :data:`FOOT_RUNS`,
    one tube per stretch over which the cut *is* one closed curve, joined by
    :func:`primitives.fork_faces` between vertices that already exist — the
    construction §7.300 gave the hand, so the foot and its five toes come out
    as one surface with one set of normals across every join.

    A refusal is **reported, not patched** (一之一): a fork whose mother ring
    does not fall into two contiguous arcs leaves its two children hanging,
    which is a hole, so it goes into *record* for the caller to put in
    ``absent``.  ``record`` is read by :func:`build_body_mesh`, which is the
    channel that matters — §7.300 wrote three runs' refusals into a dict
    nobody read.
    """
    fs = mul(p, "body.foot_size", 0.82, 1.18)
    ankle = skel.world_position(f"cf_j_leg03_{side}")
    sgn = 1.0 if side == "L" else -1.0
    # One unit for all three axes, scaled about the **ground**, so a bigger foot
    # is a bigger foot and not one hovering over the floor.
    unit = prop.height * fs
    ground = FOOT_SOLE_Y * prop.height

    def ring(row):
        dz, hw, xo, lower, upper = row
        return _foot_ring(hw * unit, ankle[0] + sgn * xo * unit,
                          [ground + q * unit for q in lower],
                          [ground + q * unit for q in upper],
                          ankle[2] + dz * unit, sgn)

    def point(end):
        dz, xo, y = FOOT_APEX[end]
        return np.array([ankle[0] + sgn * xo * unit, ground + y * unit,
                         ankle[2] + dz * unit], dtype=np.float64)

    # The half-cells past the heel's outermost station, from :data:`FOOT_TIP`,
    # then a cone onto the point it reaches.  **The distal end takes neither**:
    # it is a fork now, and a cap standing in a fork is the plate §7.283
    # measured on the palm — 24 visible vertices, 100% of them more than 30°
    # out.  ``loft`` has taken the two ends separately since §7.285.
    k = detail.n(FOOT_END_RINGS_BASE, 2)
    rings = ([ring(r[1:]) for r in _foot_end_rows("heel", k)]
             + [ring(row) for row in FOOT_SECTIONS])
    mesh = prim.loft(rings, True, True, False, f"foot_{side}",
                     start_apex=point("heel"))

    # ``(last ring, first ring)`` per run; run 0 is the foot itself, whose first
    # ring is the heel's and belongs to no fork.
    ends: dict = {0: (_loft_ring_ids(0, len(rings[0]), len(rings), -1), None)}
    for k_run, run in enumerate(FOOT_RUNS, start=1):
        base = mesh.vertex_count
        # **The first cell belongs to the fork's strip** (:func:`fork_run_rows`),
        # so what is lofted here starts one cell in.
        sec = fork_run_rows(run)
        if run["form"] == "ray":
            sides = foot_run_sides(len(run["outline"][0][1]))
            rows = [_foot_ray_ring(r1 * unit, r2 * unit,
                                   ankle[0] + sgn * cx * unit,
                                   ground + cy * unit, run["outline"], dz,
                                   ankle[2] + dz * unit, sgn, sides)
                    for dz, r1, r2, cx, cy in sec]
        else:
            rows = [ring(row) for row in sec]
        apex = run.get("apex")
        tip = (np.array([ankle[0] + sgn * apex[1] * unit,
                         ground + apex[2] * unit,
                         ankle[2] + apex[0] * unit], dtype=np.float64)
               if apex is not None else None)
        mesh.append(prim.loft(rows, True, False, tip is not None,
                              f"toe{k_run}_{side}", end_apex=tip))
        ends[k_run] = (_loft_ring_ids(base, len(rows[0]), len(rows), -1),
                       _loft_ring_ids(base, len(rows[0]), len(rows), 0))

    # ---- the four forks -----------------------------------------------------
    kids: dict = {}
    for k_run, run in enumerate(FOOT_RUNS, start=1):
        kids.setdefault(int(run["parent"]), []).append(k_run)
    for parent, two in sorted(kids.items()):
        name = "+".join("".join(FOOT_RUNS[i - 1]["toes"]) for i in two)
        if len(two) != 2:
            if record is not None:
                record.setdefault("fork_absent", []).append(
                    f"run {parent} has {len(two)} children ({name})")
            continue
        info: dict = {}
        added, why = prim.fork_faces(mesh, ends[parent][0], ends[two[0]][1],
                                     ends[two[1]][1], info=info)
        if why and record is not None:
            record.setdefault("fork_refused" if not added else "fork_warn",
                              []).append(
                f"{name} ({why}; arcs {info.get('arc_a')}/"
                f"{info.get('arc_b')})")

    mid = rings[len(rings) // 2].mean(axis=0)
    prim.ensure_outward(mesh, mid)
    mesh.compute_normals()
    return mesh


def skin_material(p: dict) -> Material:
    """The ``body`` part's material before a card's own body replaces it.

    ``body.skin_color`` is the source — it is what ``cardimport`` writes the
    card's ``skinMainColor`` into.  There used to be a preset tone table
    indexed by ``body.skin_tone`` in front of this, but the schema always
    supplies a colour, so the table's result was overwritten every time it was
    read; the slider drove nothing and is gone with it.
    """
    base = tuple((p.get("body.skin_color") or (0.988, 0.855, 0.792))[:3])
    tan = sv(p, "body.tan", 0.0)
    base = tuple(m3.lerp(np.array(base), np.array(base) * np.array([0.86, 0.72, 0.60]), tan))
    shadow = p.get("body.skin_shadow") or (0.86, 0.72, 0.76)
    return Material(
        name="skin",
        base_color=(*base, 1.0),
        shadow_color=(*shadow[:3], 1.0),
        specular_strength=rng(p, "body.skin_gloss", 0.0, 0.30, 0.16),
        specular_power=90.0,
        rim_strength=rng(p, "body.skin_rim", 0.0, 0.40, 0.35),
        rim_color=(1.0, 0.94, 0.92, 1.0),
        outline_color=tuple(np.array([*base, 1.0]) * np.array([0.42, 0.33, 0.36, 1.0])),
        outline_width=rng(p, "render.outline_width", 0.4, 2.2, 0.5),
        shade_steps=rng(p, "render.shade_steps", 1.0, 4.0, 0.34),
        shade_feather=rng(p, "render.shade_feather", 0.01, 0.20, 0.35),
        shade_offset=0.02,
    )


# Which bones each part of the skin follows, in order along it.  These are the
# ``cf_s_*`` **shape** bones, and that is the whole point: Origin's character editor
# drives the body through them (44 body sliders → 249 writes over 85 bones,
# §7.162), so a skin bound to anything else cannot be shaped by the editor's
# controls at all — measured, our own scaffold matched 0 of those 85.
#
# ``{s}`` is the side.  A name that is not on the skeleton is reported, not
# skipped silently: the trunk falling back to one bone looks like a stiff body,
# not like an error.
# The trunk chain ends at ``cf_s_head``, not at ``cf_s_neck``, and that is
# measured: on ``o_body_a`` the weight the head bone carries runs 0.09 / 0.12 /
# 0.28 / 0.43 / 0.73 / **1.00** at 0.845 / 0.850 / 0.855 / 0.860 / 0.865 / 0.875
# of stature — the top of the neck stub is head skin, on both sexes to three
# decimals (§7.233).  N14's "12.8% of the weight is on ``cf_s_head``" is the
# reading at 0.850 alone, and taking it for the whole top understates it by six
# times; the body has no head **mesh** here, which is what made that easy to
# miss.  Ending at the neck put all of it on ``cf_s_neck``, so ``NeckW`` moved
# skin Origin does not move (×2.26 against Origin's amplitude) and ``HeadSize`` moved
# nothing at all.
SKIN_CHAINS = {
    "torso": ("cf_s_waist02", "cf_s_waist01", "cf_s_spine01", "cf_s_spine02",
              "cf_s_spine03", "cf_s_neck", "cf_s_head"),
    "arm": ("cf_s_shoulder02_{s}", "cf_s_arm01_{s}", "cf_s_arm02_{s}",
            "cf_s_arm03_{s}", "cf_s_elbo_{s}", "cf_s_forearm01_{s}",
            "cf_s_forearm02_{s}", "cf_s_wrist_{s}", "cf_s_hand_{s}"),
    "leg": ("cf_s_thigh01_{s}", "cf_s_thigh02_{s}", "cf_s_thigh03_{s}",
            "cf_s_leg01_{s}", "cf_s_leg02_{s}", "cf_s_leg03_{s}",
            "cf_j_foot_{s}"),
}

#: The digits and the foot as **chains**, which is what they are.
#:
#: Not part of :data:`SKIN_CHAINS`, because a hand is five chains meeting at a
#: palm and one list running thumb → little would tie the little finger to the
#: thumb.  They are here because they answer the same question ``SKIN_CHAINS``
#: does — *which pairs of bones share a stretch of skin* — and both the ruler
#: (``--chain-share``) and :func:`weight_to_nearest_chain` read this one list.
DIGIT_CHAINS = {f: tuple(f"cf_j_{f}0{i}_{{s}}" for i in range(1, n + 1))
                for f, n in (("thumb", 3), ("index", 3), ("middle", 3),
                             ("ring", 3), ("little", 3))}
FOOT_CHAINS = {"foot": ("cf_j_foot_{s}", "cf_j_toes_{s}")}

#: The nipple, which is a chain like the others and was not on this list.
#:
#: :func:`build_body_mesh` spelled these four bones inline, so ``--chain-share``
#: — whose whole job is "the ruler cannot measure a pair the generator never
#: asks about, or miss one it does" — never saw them, and the blend they got was
#: the straight ramp §7.270 measured and replaced everywhere else.  One name,
#: read by both (七: 同一件事不要留兩套實作).
#:
#: ``cf_s_bnip015`` is deliberately not here: it carries **0 vertices on both
#: sides** of Origin's own body (§7.204), so a segment through it would be two cells
#: of nothing between two real ones.
NIPPLE_CHAINS = {"nipple": ("cf_s_bust03_{s}", "cf_s_bnip01_{s}",
                            "cf_s_bnip025_{s}", "cf_j_bnip02_{s}")}

_CHAINS = {**SKIN_CHAINS, **DIGIT_CHAINS, **FOOT_CHAINS, **NIPPLE_CHAINS}


#: The bone on the **far side of a chain's proximal joint**.
#:
#: A chain is a polyline of bones and it has to start somewhere, and where it
#: started, :func:`weight_along_chain` handed the first bone the vertex outright
#: — ``share`` is 0 at ``t = 0``, so the skin at the top of the thigh rode
#: ``cf_s_thigh01`` at a weight of exactly **1.0**.  That is the same kind of
#: claim the straight ramp was (§7.270): a chain's *proximal end* is a joint like
#: every other one, and Origin measurably blends across it.  Asked at each terminal
#: bone — pool the vertices it carries (w > 0.05) and rank what they *also*
#: carry:
#:
#:   ``cf_s_thigh01_L``     ``cf_s_waist02`` **18.7%**, ``cf_s_siri_L`` 12.2%
#:   ``cf_s_shoulder02_L``  ``cf_s_spine03`` **29.1%** (against 31.9% for itself)
#:   ``cf_j_index01_L``     ``cf_s_hand_L`` **18.0%**  (12.6–36.9% over the five)
#:
#: while the **distal** ends carry nothing from outside — a fingertip reads 83%
#: itself and 17% the knuckle behind it, which the chain already covers.  So the
#: anchor is one-ended by measurement, not by convention.
#:
#: It is **not** a tenth bone on the front of the polyline, and that was tried
#: first: ``cf_s_waist02`` sits 83 mm inboard of ``cf_s_thigh01`` and only 25 mm
#: above it, so the segment to it runs across the crotch and owns the crotch's
#: vertices — measured, Origin's share on that segment is 0.00 in all ten cells,
#: while the skin that actually tears is 20–60 mm *below* ``cf_s_thigh01``, on
#: the chain's own first segment.  The arm's anchor would have worked that way
#: and the leg's and the fingers' would not, so the anchor is expressed where
#: all three agree: as a third influence over the segment the vertex is already
#: on (:data:`ANCHOR_SHARE`).
#:
#: ``torso`` deliberately has none.  Its proximal end is the crotch, and what is
#: on the far side of *that* is two legs — a fork, not a joint (§7.252), and a
#: single polyline cannot express it.  The leg's own anchor covers the vertices
#: that showed the tear.
#: ``nipple``'s anchor is measured the same way and by the same ruler, which
#: now prints the ranking (``--chain-share``, both ends of every chain): the 586
#: vertices ``cf_s_bust03_L`` carries also ride ``cf_s_bust02_L`` **21.3%** and
#: ``cf_s_bust01_L`` 11.4%, against 43.7% for itself — the same signature as the
#: thigh's 18.7% and the shoulder's 29.1%.  ``cf_s_bust02`` is the parent joint,
#: ``bust01`` is one further out and reads half as much, so the anchor is the
#: nearer one.  The distal end (``cf_j_bnip02``, n 227) rides **nothing** off
#: the chain — one-ended, like every other chain here.
CHAIN_ANCHOR = {
    "arm": "cf_s_spine03",
    "leg": "cf_s_waist02",
    "nipple": "cf_s_bust02_{s}",
    **{f: "cf_s_hand_{s}" for f in DIGIT_CHAINS},
}

#: Every chain :data:`CHAIN_SHARE` has a row for.  One list so the ruler cannot
#: measure a pair the generator never asks about, or miss one it does.
SHARE_CHAINS = dict(_CHAINS)


# How Origin divides a vertex between two neighbouring bones of a skin chain,
# measured with
#
#   python tools/body_profile.py --chain-share --sex 0 --emit
#
# ``share[i]`` is ``w(b) / (w(a) + w(b))`` at ``t = (i + 0.5) / 10`` along the
# segment, over the vertices that segment owns **and** that pair carries.
# :func:`weight_along_chain` used to write the share as ``t`` itself — a
# straight ramp between the two bones — and that is a claim, not a neutral
# choice.  Measured, it is wrong by a lot in specific places, and always in the
# direction of handing a shape bone skin the artist never gave it:
#
#   ``cf_s_spine03 -> cf_s_neck``   Origin gives the neck **0.000 until t = 0.85**,
#       we gave it 0.05..0.95.  That is why our ``cf_s_neck`` carried 1,018
#       vertices out to 146 mm where Origin's carries 166 out to 77, and why a
#       neck-width slider widened our shoulders (``NeckW`` x2.63, §7.269).
#   ``cf_s_arm03 -> cf_s_elbo``     0.000 until t = 0.65.  ``cf_s_elbo`` is a
#       shape bone parked on the olecranon, **behind** the arm, not a joint on
#       the centreline (§7.198) — the artist barely skinned to it, and the
#       polyline blend cannot know that.
#   ``cf_s_leg03 -> cf_j_foot``     already 0.44 in the first cell: the ankle
#       hands over far sooner than a straight ramp does.
#
# What is transferred is the **share**, not the weights.  Origin's vertices give
# part of themselves to bones our body does not carry, so its weights do not
# sum to one over any pair and could not be copied even in principle; the split
# between two named bones is the same quantity our blend produces, and it is a
# fact about where the artist divided that stretch of skin.
#
# A pair missing from the table keeps the straight ramp, and that is a
# measurement too: ``cf_s_waist01 -> cf_s_spine01`` is 10 mm long, so only 12
# vertices are nearest to it — withheld rather than guessed (§7.192).
#
# Two full tables rather than one plus a patch: 19 of the 32 rows are identical
# between the sexes (the limbs are the same skin), but a table that can only be
# read through another table gets half-updated by the next person (七).  Three
# of the rest are the nipple, which the male table does not have at all.

