# How much of a chain's own skin its :data:`CHAIN_ANCHOR` takes, measured with
#
#   python tools/body_profile.py --chain-share --sex 0 --emit
#
# in the same ten cells and the same ``t`` as :data:`CHAIN_SHARE`, over the
# vertices that segment owns **and** the chain carries (``w`` over the chain's
# own bones > 0.05).  That filter is the whole measurement: asking instead for
# ``w(anchor) + w(chain) > 0.05`` admits pure trunk skin — 951 vertices nowhere
# near the arm, every one of them reading 1.000 — and turns a decay curve into a
# plateau (§7.269 七, again).
#
# A pair with no row here gets **0**, and that is a reading rather than a
# default: the ruler prints every segment of every chain, and past the first one
# or two the anchor is gone (the arm's ``cf_s_spine03`` is under 0.02 by 30 mm
# out of 534, the fingers' ``cf_s_hand`` by 20–45 mm out of 46–62).  Only the
# leg reaches far, and it reaches exactly as far as the hip crease.
#
# The vertex ends up with three influences: ``a`` on the anchor and the
# remaining ``1 - a`` split between the segment's own two bones by
# :data:`CHAIN_SHARE`.  Both factors are ratios of Origin's own weights measured
# independently, so the decomposition does not double-count.
#
# Six of the eleven rows are the same on both sexes, which is the same split
# :data:`CHAIN_SHARE` shows: the limbs are one skin, the trunk is two, and the
# nipple is on one of them only.
