def _branch_bins():
    """The centres of :data:`BRANCH_DIR_EDGES`' bins."""
    e = BRANCH_DIR_EDGES
    return np.array([(a + b) / 2.0 for a, b in zip(e[:-1], e[1:])])


def _branch_columns(cells):
    """*cells* with each row's withheld direction bins filled from its own.

    A ``None`` is a bin the ruler could not read — too few of Origin's vertices lie
    that way at that distance — and the fill is the row's **own** measured bins
    interpolated across, held flat outside them.  Not a neutral value: 0 there
    would say "this bone stops in that direction", which is a measurement
    nobody made, and §7.186 is the same lesson from the other side (a missing
    sample filled with 1.0 came out as a rectangular slab with four hard edges).
    Flat outside is what the bins beyond our own surface get, and no vertex of
    ours is ever there — that is *why* they are empty.
    """
    mid = _branch_bins()
    out = np.zeros((len(cells), len(cells[0][1])))
    for i, (_x, row) in enumerate(cells):
        have = [(mid[j], v) for j, v in enumerate(row) if v is not None]
        if not have:
            continue
        if len(have) == 1 or len(row) == 1:
            out[i, :] = have[0][1]
        else:
            out[i] = np.interp(mid, [h[0] for h in have], [h[1] for h in have])
    return out


def _branch_at(chain: str, tmpl: str, d, u, sex: int):
    """:data:`BRANCH_SHARE` at distance *d* (stature fractions) and direction
    *u*, else 0.

    Zero past the last station rather than the flat hold ``np.interp`` gives by
    default: this is the share of a **local** joint, and the far side of the
    trunk is 200–400 mm from a shoulder.  The step that makes is 0.001 — the
    last measured cell — so nothing turns on which of the two it is; what turns
    on it is that the table cannot quietly grow a tail nobody measured (§7.209).
    Flat *inside* the first station, because that one is a lower bound and the
    cells behind it were withheld rising.

    *u* is the vertex's unit direction from the bone, already mirrored onto the
    left side by the caller; the cosine against the row's **own measured axis**
    is taken here, so the axis has one reader.  A row of one value per station
    has no axis and ignores *u* — that is what a branch whose share does not
    resolve in direction looks like, written down rather than left implicit.
    """
    tab = (BRANCH_SHARE_M if sex == 1 else BRANCH_SHARE).get((chain, tmpl))
    d = np.asarray(d, dtype=np.float64)
    if not tab:
        return np.zeros_like(d)
    axis, cells = tab[0], tab[1:]
    xs = np.array([x for x, _row in cells])
    cols = _branch_columns(cells)
    if axis is None or cols.shape[1] == 1:
        return np.interp(d, xs, cols[:, 0], right=0.0)
    # Interpolate in the direction first — every station is a curve in ``c`` —
    # and then between the two stations that bracket the vertex.  The other
    # order would need a table of ``d`` curves per bin and give the same answer
    # for a bilinear patch; this way the "flat outside the bins" reading lives
    # in one place.
    c = np.asarray(u, dtype=np.float64) @ np.asarray(axis, dtype=np.float64)
    per = np.stack([np.interp(c, _branch_bins(), cols[i])
                    for i in range(len(xs))], axis=-1)
    if len(xs) == 1:
        return np.where(d > xs[0], 0.0, per[:, 0])
    k = np.clip(np.searchsorted(xs, d), 1, len(xs) - 1)
    f = np.clip((d - xs[k - 1]) / (xs[k] - xs[k - 1]), 0.0, 1.0)
    r = np.arange(len(d))
    return np.where(d > xs[-1], 0.0,
                    per[r, k - 1] * (1.0 - f) + per[r, k] * f)


def _share_at(pair: tuple[str, str], t, sex: int):
    """:data:`CHAIN_SHARE` at *t*, or ``t`` itself where it says nothing.

    The table's entries are cell **centres** (0.05 … 0.95), so ``np.interp``
    holds the end cells flat outside them.  That is the reading the measurement
    supports — the first cell *is* what Origin does over ``t`` 0…0.1 — and it is
    not the failure §7.209 caught, where a table of radii was extrapolated past
    stations it never measured.
    """
    tab = (CHAIN_SHARE_M if sex == 1 else CHAIN_SHARE).get(pair)
    if tab is None:
        return t
    xs = [(i + 0.5) / len(tab) for i in range(len(tab))]
    return np.interp(t, xs, tab)


def _branch_of(mesh: Mesh, skel: Skeleton, chain: str, height: float, sex: int):
    """``([(share, bone id), …], missing)`` per vertex for *chain*'s branches.

    One entry per :data:`CHAIN_BRANCH` template this armature carries, in the
    table's own order.  Which side is the vertex's own ``x``, because the two
    bones of a template are mirrors and :data:`BRANCH_SHARE` is under 0.01 well
    before the two catchments meet at the midline: picking the nearer of the two
    would be the same answer with a tie to break.

    ``([], missing)`` when the chain has no branch or the armature has neither
    bone — the bare procedural scaffold carries no ``cf_s_*`` at all (§7.162),
    and that is a report, not a reason to bind nothing.

    The table is in stature fractions and the mesh is in metres at whatever
    stature this build has, so *height* is what divides them (§7.213: measure
    both sides in the coordinate they share, not the one each can compute).
    """
    tmpls = CHAIN_BRANCH.get(chain)
    if not tmpls:
        return [], []
    missing: list[str] = []
    if height <= 0.0:
        # Its own sentence, because "the armature has no shoulder" and "nobody
        # told me the stature the table is read in" have different fixes and
        # one string for both would hide whichever is not happening (§7.138).
        return [], [f"{chain}: no stature to read BRANCH_SHARE in"]
    v = mesh.positions.astype(np.float64)
    out = []
    for tmpl in tmpls:
        names = {s: tmpl.format(s=s) for s in ("L", "R")}
        have = {s: skel.id(n) for s, n in names.items() if skel.has(n)}
        missing.extend(n for s, n in names.items() if s not in have)
        if not have:
            continue
        bid = np.zeros(len(v), dtype=np.int64)
        off = np.zeros((len(v), 3))
        only = next(iter(have))
        side = np.where(v[:, 0] >= 0.0, "L", "R") if len(have) > 1 else \
            np.full(len(v), only)
        for s, i in have.items():
            m = side == s
            if not m.any():
                continue
            o = skel.bones[i].bind_world[:3, 3]
            bid[m] = i
            off[m] = v[m] - o
        # **The right side is mirrored onto the left before the direction is
        # read.**  The two bones are mirrors, so the table's axis — measured
        # once, on the left — points the wrong way round the body on the right;
        # the same fact §7.257 caught the other way about, where a table
        # measured on the left was consumed at ``+θ`` on both sides and five
        # sections read the result as scatter.  Distance is blind to it, which
        # is why it could not come up before this row had an axis.
        off[side == "R", 0] *= -1.0
        d = np.linalg.norm(off, axis=1)
        u = off / np.maximum(d, 1e-12)[:, None]
        out.append((_branch_at(chain, tmpl, d / height, u, sex), bid))
    return out, missing


def weight_along_chain(mesh: Mesh, skel: Skeleton, names: list[str],
                       sex: int = 0, anchor: str = "",
                       chain: str = "", height: float = 0.0,
                       smooth: bool = False) -> list[str]:
    """Bind every vertex to the two nearest bones **along** *names*.

    The vertex is projected onto the polyline through the bones' origins and
    blended between the segment's two ends, rather than onto the straight line
    from the first bone to the last: a leg chain bends at the knee and a trunk
    chain leans, and a straight-line parameter puts the knee's vertices on the
    thigh.  (``genitals._weight_chain`` uses the two-endpoint form because a
    shaft is straight; this one cannot.)

    **How much of the vertex each end gets is** :data:`CHAIN_SHARE`, not ``t``.
    A straight ramp is what this wrote for ten sections and it is a claim about
    the artist's weighting that turns out to be wrong wherever a shape bone is
    parked off the centreline — see the table's own note.  Pairs the table does
    not name keep the ramp.

    *anchor* is the bone across the chain's **proximal** joint
    (:data:`CHAIN_ANCHOR`).  It takes :data:`ANCHOR_SHARE` of the vertex and the
    two chain bones divide what is left.  Without one, the chain's first bone
    took the skin at ``t = 0`` outright, at a weight of exactly 1.0 — which is
    what tore the hip open under a 45° bend.

    *chain* names the chain, which is what :data:`CHAIN_BRANCH` is keyed on: the
    bone across a joint the chain passes **sideways**, taking
    :data:`BRANCH_SHARE` before the anchor and the pair divide what is left.
    Without it the trunk had nowhere to put the shoulders and the neck took them
    — a neck-width slider then moved our shoulder skin 2.2 times as far as Origin's.
    *height* is the stature that table is read in.

    **``smooth`` belongs here and not at the call site, because it is an
    ordering and the branches sit on both sides of it.**  :func:`smooth_weights`
    exists for the *pair*: a two-bone blend is linear in the projection onto the
    chain, so where one bone's scale differs from the next the surface steps.  A
    branch is not that — it is a measured field in its own coordinate, already
    smooth — and diffusing it only erodes its peak, which §7.278 priced at 0.817
    on the male bust family.  So the pair and the anchor are written, diffused,
    and the branches go on top of the result (§7.280).

    Returns the names this skeleton does not have.
    """
    ids, missing, kept = [], [], []
    for n in names:
        if skel.has(n):
            ids.append(skel.id(n))
            kept.append(n)
        else:
            missing.append(n)
    if not ids:
        return missing
    anchor_id = skel.id(anchor) if anchor and skel.has(anchor) else None
    if anchor and anchor_id is None:
        missing.append(anchor)
    if len(ids) == 1:
        mesh.set_bone(ids[0])
        return missing
    branches, br_missing = _branch_of(mesh, skel, chain, height, sex)
    missing.extend(br_missing)
    pts = np.array([skel.bones[i].bind_world[:3, 3] for i in ids],
                   dtype=np.float64)
    v = mesh.positions.astype(np.float64)
    seg = pts[1:] - pts[:-1]
    seg_len2 = np.einsum("ij,ij->i", seg, seg) + 1e-12

    best_d = np.full(len(v), np.inf)
    best_k = np.zeros(len(v), dtype=np.int64)
    best_t = np.zeros(len(v))
    for k in range(len(seg)):
        t = np.clip((v - pts[k]) @ seg[k] / seg_len2[k], 0.0, 1.0)
        foot = pts[k] + t[:, None] * seg[k]
        d = np.linalg.norm(v - foot, axis=1)
        take = d < best_d
        best_d = np.where(take, d, best_d)
        best_k = np.where(take, k, best_k)
        best_t = np.where(take, t, best_t)

    mesh.bone_idx[:] = 0
    mesh.bone_wt[:] = 0.0
    rows = np.arange(len(v))
    missing.extend(_write_chain(mesh, rows, ids, kept, best_k, best_t, sex,
                                anchor_id, None if smooth else branches,
                                chain))
    if smooth:
        smooth_weights(mesh)
        missing.extend(_put_branches(mesh, rows, branches, chain))
    return missing


def _write_chain(mesh: Mesh, rows, ids, kept, best_k, best_t, sex, anchor_id,
                 branches=None, chain: str = "") -> list[str]:
    """Put ``(anchor, branches…, b_k, b_k+1)`` on *rows*, from the tables.

    One copy, because both binders need it and a second one would drift: the
    share and the anchor are looked up per **segment** — the pair's names with
    the side stripped, since a chain's split is not per side (measured: the two
    bakes give the same numbers for L and R).

    *branches* is :func:`_branch_of`'s list of ``(share, bone id)``, already
    looked up per vertex, and **only on chains that are not smoothed**: where
    there is a ramp to diffuse, :func:`weight_along_chain` holds them back and
    :func:`_put_branches` lays them on afterwards (§7.280).  Written here each
    composes exactly as the anchor does — it takes its share of the whole vertex
    and the rest is divided as before — so they are measured independently and
    none double-counts another.  What the slots cannot hold is trimmed and
    reported by :func:`_branch_slots`.
    """
    note: list[str] = []
    share = np.array(best_t, dtype=np.float64)
    anch = np.zeros(len(best_t))
    for k in range(len(kept) - 1):
        m = best_k == k
        if not m.any():
            continue
        pair = (_side_free(kept[k]), _side_free(kept[k + 1]))
        share[m] = _share_at(pair, best_t[m], sex)
        if anchor_id is not None:
            anch[m] = _anchor_at(pair, best_t[m], sex)
    idx = np.asarray(ids, dtype=np.int64)
    rows = np.asarray(rows)
    slot = 3 if anchor_id is not None else 2
    free = mesh.bone_wt.shape[1] - slot
    bw, bi, note2 = _branch_slots(branches, rows, free, 1.0 - anch, chain)
    note.extend(note2)
    br = bw.sum(axis=1) if bw is not None else np.zeros(len(rows))
    mesh.bone_idx[rows, 0] = idx[best_k]
    mesh.bone_idx[rows, 1] = idx[best_k + 1]
    mesh.bone_wt[rows, 0] = (1.0 - anch - br) * (1.0 - share)
    mesh.bone_wt[rows, 1] = (1.0 - anch - br) * share
    if anchor_id is not None:
        mesh.bone_idx[rows, 2] = anchor_id
        mesh.bone_wt[rows, 2] = anch
    if bw is not None:
        for j in range(bw.shape[1]):
            mesh.bone_idx[rows, slot + j] = bi[:, j]
            mesh.bone_wt[rows, slot + j] = bw[:, j]
    return note


def _branch_slots(branches, rows, free: int, room, chain: str):
    """``(shares, bone ids, notes)`` for *rows*, trimmed to *free* slots.

    One copy for both orderings — :func:`_write_chain` writes the branches with
    the pair, :func:`_put_branches` writes them after the ramp has been
    diffused, and a second copy of this arithmetic would drift.  Both ways it
    can bite are reports rather than silence (一之一):

    * more overlapping branches than free slots — the weakest are dropped, and
      what they were holding goes back to the chain pair, which is where it was
      before the branch existed;
    * the shares summing past *room* — scaled down together, so the split
      between them is kept and only the total moves.
    """
    note: list[str] = []
    branches = list(branches or ())
    if not branches:
        return None, None, note
    rows = np.asarray(rows)
    bw = np.stack([np.asarray(w, dtype=np.float64)[rows]
                   for w, _i in branches], axis=1)
    bi = np.stack([np.asarray(i)[rows] for _w, i in branches], axis=1)
    if bw.shape[1] > free:
        # Strongest first, so what is dropped is the smallest share the vertex
        # had — and how much that was is the number below, not an assumption
        # that it is negligible.
        order = np.argsort(-bw, axis=1)
        keep, rest = order[:, :free], order[:, free:]
        lost = np.take_along_axis(bw, rest, axis=1).sum(axis=1)
        if float(lost.max()) > 1e-4:
            note.append(f"{chain or 'chain'}: {int((lost > 1e-4).sum())} "
                        f"vertices are inside more than {free} branch "
                        f"catchments; dropped up to {lost.max():.3f} of a "
                        "vertex back onto the chain pair")
        bw = np.take_along_axis(bw, keep, axis=1)
        bi = np.take_along_axis(bi, keep, axis=1)
    room = np.broadcast_to(np.asarray(room, dtype=np.float64),
                           (len(rows),)).copy()
    tot = bw.sum(axis=1)
    over = tot > room
    if over.any():
        note.append(f"{chain or 'chain'}: {int(over.sum())} vertices' branch "
                    f"shares sum past the {room.min():.3f} left for them "
                    f"(worst {tot.max():.3f}); scaled down together")
        bw[over] *= (room[over] / np.maximum(tot[over], 1e-12))[:, None]
    return bw, bi, note


def _put_branches(mesh: Mesh, rows, branches, chain: str = "") -> list[str]:
    """Lay the branches on top of weights that are already written.

    The counterpart to writing them inside :func:`_write_chain`: each branch
    takes its measured share **of the whole vertex** and everything already
    there is scaled by what is left, which keeps the partition of unity without
    a renormalising pass.  Three things about this ordering are not free and are
    named rather than left to be found:

    * the anchor pays its share too.  Written with the pair, the anchor keeps
      all of :data:`ANCHOR_SHARE` and only the pair pays; here everyone does.
      Measured, that is the leg's proximal end and nowhere else — the only
      place a chain has both.
    * the branch is written **unsmoothed**, which is the point (§7.280).
    * **there are no free slots left to write into.**  :func:`smooth_weights`
      finishes by keeping each vertex's four strongest bones, so every slot is
      taken by the time this runs; the branch cannot claim an empty one the way
      it can before the ramp.  So the two sets are merged densely and the four
      strongest of the union survive — which drops whichever influence is
      weakest rather than always the branch, and how much that came to is
      reported (一之一).
    """
    rows = np.asarray(rows)
    branches = list(branches or ())
    if not len(rows) or not branches:
        return []
    bw, bi, note = _branch_slots(branches, rows, len(branches), 1.0, chain)
    if bw is None:
        return note
    K = mesh.bone_idx.shape[1]
    keep = 1.0 - bw.sum(axis=1)
    ai = np.concatenate([mesh.bone_idx[rows].astype(np.int64), bi], axis=1)
    aw = np.concatenate([mesh.bone_wt[rows].astype(np.float64)
                         * keep[:, None], bw], axis=1)
    # A branch bone can already be in the row's slots — it cannot have diffused
    # in here (the branches were not written before the ramp) but the chain
    # itself may name it, and two columns holding the same bone would let the
    # ``top-K`` below keep one and throw the other away.
    for j in range(K, ai.shape[1]):
        same = (ai[:, :j] == ai[:, j:j + 1]) & (aw[:, :j] > 0.0)
        hit = same.any(axis=1)
        if not hit.any():
            continue
        first = np.argmax(same[hit], axis=1)
        aw[np.flatnonzero(hit), first] += aw[hit, j]
        aw[hit, j] = 0.0
    order = np.argsort(-aw, axis=1)
    top_i = np.take_along_axis(ai, order[:, :K], axis=1)
    top_w = np.take_along_axis(aw, order[:, :K], axis=1)
    lost = np.take_along_axis(aw, order[:, K:], axis=1).sum(axis=1)
    if float(lost.max(initial=0.0)) > 1e-4:
        note.append(f"{chain or 'chain'}: laying the branches on the smoothed "
                    f"ramp pushed a {lost.max():.3f} influence off "
                    f"{int((lost > 1e-4).sum())} vertices (four slots)")
    tot = top_w.sum(axis=1, keepdims=True)
    tot[tot <= 0] = 1.0
    mesh.bone_idx[rows] = top_i.astype(mesh.bone_idx.dtype)
    mesh.bone_wt[rows] = (top_w / tot).astype(mesh.bone_wt.dtype)
    return note


def _side_free(name: str) -> str:
    """``cf_s_arm01_L`` -> ``cf_s_arm01``."""
    return name[:-2] if name.endswith(("_L", "_R")) else name


def weight_to_nearest(mesh: Mesh, skel: Skeleton, names: list[str]) -> list[str]:
    """Bind each vertex rigidly to whichever of *names* is closest.

    Fingers and toes are their own short chains and a vertex belongs to exactly
    one of them — blending along a list that jumps from one digit to the next
    would tie the little finger to the thumb.
    """
    ids = [skel.id(n) for n in names if skel.has(n)]
    missing = [n for n in names if not skel.has(n)]
    if not ids:
        return missing
    pts = np.array([skel.bones[i].bind_world[:3, 3] for i in ids],
                   dtype=np.float64)
    v = mesh.positions.astype(np.float64)
    d = np.linalg.norm(v[:, None, :] - pts[None, :, :], axis=2)
    near = np.asarray(ids, dtype=np.int64)[np.argmin(d, axis=1)]
    mesh.bone_idx[:] = 0
    mesh.bone_wt[:] = 0.0
    mesh.bone_idx[:, 0] = near
    mesh.bone_wt[:, 0] = 1.0
    return missing


def weight_to_nearest_chain(mesh: Mesh, skel: Skeleton, chains, sex: int = 0,
                            anchors=None) -> list[str]:
    """Nearest bone picks the **chain**; :data:`CHAIN_SHARE` divides within it.

    :func:`weight_to_nearest` is right about *which* digit a vertex belongs to
    and wrong about everything after that: it hands the vertex entirely to one
    bone, so the skin's handover from one phalanx to the next falls at the
    **midpoint between the two bone origins** and falls there as a step.

    Measured against Origin (``--chain-share``, and the digit chains had never been
    asked):

        ``cf_j_index02 -> cf_j_index03``  Origin 0.00 … 0.06 at t = 0.65 … 1.00 at
            0.95; ours stepped to 1.00 at **t = 0.55**.
        ``cf_j_foot -> cf_j_toes``        Origin 0.00 to t = 0.65, 0.08 / 0.11 /
            0.97; ours stepped to 1.00 at **t = 0.55** — on a 107 mm segment,
            a toe crease 43 mm back into the arch of the foot.

    So every crease on our hand and foot sat half a bone too far back and had
    no width.  Posed, that is the largest normal error on the body: bending the
    fingers 70° took ``seg hand`` from 18.2% of normals more than 30° off Origin to
    **38.2%** (``--vs-shape --pose fist``, §7.271).  The toe half of that
    sentence read 13.6% → 35.8% with p90 distance 0.03 → 10.19 mm, and it is
    **out of date** — re-measured on today's build (§7.303) a 45° toe flex takes
    ``seg foot`` 10.8% → **13.8%** with p90 0.04 → **0.94 mm**, and the foot
    before the fork cascade read the same 13.8% and 0.83 mm, so it is not the
    cascade that moved it.

    *chains* is a list of name lists.  A one-bone chain is allowed and means
    exactly what :func:`weight_to_nearest` did — the palm is one.  *anchors* is
    the matching list of :data:`CHAIN_ANCHOR` bones (``""`` for none); a finger's
    is ``cf_s_hand``, which is also the palm's chain, so the anchor is a bone the
    vertex shares with its neighbour rather than a sixth chain — putting it on
    the front of each finger's polyline instead would have let the first finger
    in the list claim the whole palm (``argmin`` breaks ties by position).
    """
    kept, missing, anch = [], [], []
    chains = [list(c) for c in chains]
    anchors = list(anchors or []) + [""] * len(chains)
    for chain, a in zip(chains, anchors):
        have = [n for n in chain if skel.has(n)]
        missing.extend(n for n in chain if not skel.has(n))
        if a and not skel.has(a):
            missing.append(a)
            a = ""
        if have:
            kept.append(have)
            anch.append(a)
    if not kept:
        return missing
    # Which chain: the nearest **bone origin**, exactly as before.  Deliberately
    # not "the nearest polyline" — that would move vertices between the palm and
    # the fingers as well, and then the change here could not be attributed to
    # the share alone.  The anchor is not in here: it belongs to the chain's
    # weighting, not to its catchment (it is the *neighbouring* part's bone).
    flat = [(ci, n) for ci, chain in enumerate(kept) for n in chain]
    pts = np.array([skel.bones[skel.id(n)].bind_world[:3, 3] for _c, n in flat],
                   dtype=np.float64)
    v = mesh.positions.astype(np.float64)
    d = np.linalg.norm(v[:, None, :] - pts[None, :, :], axis=2)
    chain_of = np.array([c for c, _n in flat])[np.argmin(d, axis=1)]

    mesh.bone_idx[:] = 0
    mesh.bone_wt[:] = 0.0
    for ci, chain in enumerate(kept):
        m = chain_of == ci
        if not m.any():
            continue
        cids = [skel.id(n) for n in chain]
        if len(chain) == 1:
            mesh.bone_idx[m, 0] = cids[0]
            mesh.bone_wt[m, 0] = 1.0
            continue
        cp = np.array([skel.bones[i].bind_world[:3, 3] for i in cids],
                      dtype=np.float64)
        vv = v[m]
        seg = cp[1:] - cp[:-1]
        sl2 = np.einsum("ij,ij->i", seg, seg) + 1e-12
        best_d = np.full(len(vv), np.inf)
        best_k = np.zeros(len(vv), dtype=np.int64)
        best_t = np.zeros(len(vv))
        for k in range(len(seg)):
            t = np.clip((vv - cp[k]) @ seg[k] / sl2[k], 0.0, 1.0)
            dd = np.linalg.norm(vv - (cp[k] + t[:, None] * seg[k]), axis=1)
            take = dd < best_d
            best_d = np.where(take, dd, best_d)
            best_k = np.where(take, k, best_k)
            best_t = np.where(take, t, best_t)
        a = anch[ci]
        missing.extend(_write_chain(mesh, np.flatnonzero(m), cids, chain,
                                    best_k, best_t, sex,
                                    skel.id(a) if a else None))
    return missing


def _coincident_groups(pos) -> list:
    """Index groups of vertices sharing a position, longest first.

    Exact equality on purpose: these copies are written by the same expression
    (``tube_along`` closes a ring by repeating the column), not measured, so a
    tolerance would be a knob with nothing to calibrate it against — and one
    wide enough to matter would start merging a fold's two lips.
    """
    pos = np.asarray(pos, dtype=np.float64)
    if not len(pos):
        return []
    _u, inv, cnt = np.unique(pos, axis=0, return_inverse=True,
                             return_counts=True)
    inv = np.asarray(inv).ravel()
    dup = np.flatnonzero(cnt > 1)
    if not len(dup):
        return []
    order = np.argsort(inv, kind="stable")
    starts = np.searchsorted(inv[order], dup)
    return [order[s:s + int(cnt[d])] for s, d in zip(starts, dup)]


def smooth_weights(mesh: Mesh, iterations: int = 3, factor: float = 0.5) -> Mesh:
    """Average each vertex's weights with its edge neighbours' a few times.

    A two-bone blend along a chain is linear in the *projection* onto that
    chain, and the chain's bones are far apart, so where one bone's scale
    differs from the next the surface steps: ``BodyLowW`` at 1.0 put a shelf
    round the lower ribs with vertical sides.  Diffusing the weights over the
    mesh's own edges turns the step into a ramp without touching the geometry
    or the values the sliders write — the bones still do exactly what the
    editor asks, the skin just stops treating the boundary as a cliff.

    Weights stay a partition of unity: each pass is a convex combination, so
    the sum is preserved exactly rather than renormalised back afterwards.

    **The graph is the surface's, not the index buffer's.**  A UV seam
    duplicates a column of vertices, and in the index buffer the two copies are
    strangers — so diffusion lets them drift apart, and posed, the skin splits
    along the seam.  Measured before anything about the anchor changed: **144 of
    the 700 coincident groups already disagreed**, the worst by 0.550 on the
    arm; the anchor made it visible rather than made it happen, because a seam
    whose two copies both sit at a saturated 1.0 cannot show the crack.  They
    are the same point on the body, so they are linked here and equalised at the
    end — the second half so the answer does not depend on how many passes ran.
    """
    n = mesh.vertex_count
    if n == 0 or not len(mesh.indices):
        return mesh
    # Dense per-bone weights, so that neighbours contributing *different* bones
    # add instead of one overwriting the other — averaging the four (index,
    # weight) slots directly would mix bone ids as if they were numbers.
    used = sorted({int(b) for b in mesh.bone_idx[mesh.bone_wt > 0].tolist()})
    if len(used) < 2:
        return mesh
    col = {b: i for i, b in enumerate(used)}
    W = np.zeros((n, len(used)))
    for k in range(mesh.bone_idx.shape[1]):
        w = mesh.bone_wt[:, k].astype(np.float64)
        live = w > 0
        if not live.any():
            continue
        np.add.at(W, (np.where(live)[0],
                      np.array([col[int(b)] for b in mesh.bone_idx[live, k]])),
                  w[live])

    tri = mesh.indices.reshape(-1, 3)
    a = np.concatenate([tri[:, 0], tri[:, 1], tri[:, 2],
                        tri[:, 1], tri[:, 2], tri[:, 0]])
    b = np.concatenate([tri[:, 1], tri[:, 2], tri[:, 0],
                        tri[:, 0], tri[:, 1], tri[:, 2]])
    # Seam edges: every pair of vertices at the same position, both ways.
    seam = _coincident_groups(mesh.positions)
    if seam:
        sa = np.concatenate([np.repeat(g, len(g)) for g in seam])
        sb = np.concatenate([np.tile(g, len(g)) for g in seam])
        keep = sa != sb
        a = np.concatenate([a, sa[keep]])
        b = np.concatenate([b, sb[keep]])
    deg = np.bincount(a, minlength=n).astype(np.float64)
    deg[deg == 0] = 1.0
    for _ in range(max(0, iterations)):
        acc = np.zeros_like(W)
        np.add.at(acc, a, W[b])
        W = (1.0 - factor) * W + factor * (acc / deg[:, None])
    for g in seam:
        W[g] = W[g].mean(axis=0)

    order = np.argsort(-W, axis=1)[:, :mesh.bone_idx.shape[1]]
    top = np.take_along_axis(W, order, axis=1)
    tot = top.sum(axis=1, keepdims=True)
    tot[tot <= 0] = 1.0
    mesh.bone_idx[:] = np.asarray(used, dtype=np.int32)[order]
    mesh.bone_wt[:] = (top / tot).astype(np.float32)
    return mesh


def _reach_into_trunk(pts, radii, squash, torso: Mesh, prop: Proportions,
                      side: str, axis: int):
    """Add one ring at the limb's root, **inside** the trunk, and say where.

    A limb tube's root ring is open, so it has to finish under the trunk's
    surface or the viewer sees into it.  How far in "under" is has to come from
    the trunk, not from a typed offset: measured, arm and trunk each lost a few
    per cent when the sliders' neutral was corrected to 1.0 and the two stopped
    overlapping — a dark triangle opened between the neck and the deltoid
    (§7.169).  The extra ring goes to where the trunk's own surface is, less a
    margin, so it cannot re-open when either side changes thickness again.
    """
    pts = np.asarray(pts, dtype=np.float64)
    root = pts[0].copy()
    d0 = m3.normalize(pts[1] - pts[0])
    r0 = float(radii[0])
    margin = 0.004 * prop.height
    # **Where a ring of this size fits, not where the trunk is widest.**  This
    # used to take the trunk's reach over a ±0.02-of-stature band and put the
    # stub there, and both halves of that were wrong.  The band is 31 mm tall
    # and the trunk widens fast going down, so its **max** answers with a height
    # 31 mm below the root — 94.6 mm where the trunk at the root's own height is
    # 64.7 — and the stub landed 1.2 mm inside a surface it is 40.8 mm wide.
    # Measured, **12 of its 24 vertices stood outside the trunk**, with the
    # tube's cap on them.  It never showed while §7.234's typed 44 mm shift was
    # also running: that put the root deeper than this, so the early return
    # above fired and no stub was ever built.  Same sentence as ``PALM_BACK`` in
    # §7.230 — retracting a ring into a tube and fitting inside it are two
    # conditions, and only the second hides a cap.
    # Coarse scan then bisect, because the answer wanted is the **outermost**
    # place it fits: everything inboard of that is buried geometry that still
    # rides the shoulder bone, and a 40 mm ring parked next to the midline would
    # swing out through the chest as soon as the arm is posed.  The scan alone
    # overshot by 15 mm (it lands on a 19 mm grid).
    step = 0.012 * prop.height
    fallback = None
    lo = 0.0
    for k in range(1, 9):
        cand = root - d0 * (step * k)
        room = _ring_room(cand, d0, r0, torso, margin)
        if fallback is None or room > fallback[0]:
            fallback = (room, cand)
        if room >= r0:
            hi = step * k
            for _ in range(4):
                mid = 0.5 * (lo + hi)
                if _ring_room(root - d0 * mid, d0, r0, torso, margin) >= r0:
                    hi = mid
                else:
                    lo = mid
            cand = root - d0 * hi
            return (np.vstack([cand, pts]),
                    np.concatenate([[r0], radii]),
                    np.concatenate([[squash[0]], squash]))
        lo = step * k
    # Nothing along the axis holds a full ring — take the roomiest place and
    # shrink to it.  Said rather than skipped: a stub that does not fit is a
    # visible cap, and a stub that is not there is a visible hole.
    if fallback is None or fallback[0] <= 0.0:
        return pts, radii, squash
    return (np.vstack([fallback[1], pts]),
            np.concatenate([[min(r0, fallback[0])], radii]),
            np.concatenate([[squash[0]], squash]))


def _surface_reach(centre: np.ndarray, dirs: np.ndarray, host: Mesh):
    """``(nearest crossing, crossing count)`` of *host* along each of *dirs*.

    One owner for "how far is that part's skin from here, this way round".
    :func:`_ring_room` collapses it to one number to place a ring;
    :func:`_fit_inside_surface` keeps it per ray to size one.  The count comes
    back with it because parity is the only honest test of whether *centre* is
    under the skin at all, and both callers have to refuse rather than invent an
    answer when it is not (``CLAUDE.md`` 一之一).

    ``inf`` where a ray finds nothing: that direction does not constrain
    anything, and a large number would be a made-up bound.
    """
    tp = np.asarray(host.positions, dtype=np.float64)
    tri = np.asarray(host.indices, dtype=np.int64).reshape(-1, 3)
    a = tp[tri[:, 0]]
    ab, ac = tp[tri[:, 1]] - a, tp[tri[:, 2]] - a
    s = np.asarray(centre, dtype=np.float64) - a
    near = np.full(len(dirs), np.inf)
    cnt = np.zeros(len(dirs), dtype=np.int64)
    for k, d in enumerate(np.asarray(dirs, dtype=np.float64)):
        h = np.cross(d, ac)
        det = (ab * h).sum(axis=1)
        ok = np.abs(det) > 1e-14
        inv = np.where(ok, 1.0 / np.where(ok, det, 1.0), 0.0)
        u = (s * h).sum(axis=1) * inv
        q = np.cross(s, ab)
        v = (d * q).sum(axis=1) * inv
        t = (ac * q).sum(axis=1) * inv
        hit = ok & (u >= 0.0) & (u <= 1.0) & (v >= 0.0) & (u + v <= 1.0) \
            & (t > 1e-6)
        cnt[k] = int(hit.sum())
        if hit.any():
            near[k] = float(t[hit].min())
    return near, cnt


def _ring_room(centre: np.ndarray, axis_dir: np.ndarray, r0: float,
               torso: Mesh, margin: float, rays: int = 24) -> float:
    """The largest radius a ring at *centre* fits inside *torso* with.

    Cast one ray per direction of the ring's own plane and take the nearest
    crossing: that is the trunk's surface in the direction the ring's vertex is
    going, which is the only thing that decides whether that vertex ends up
    inside.  A band of trunk vertices cannot answer it — the trunk's reach is a
    function of height **and** of the way round, and a ring at the shoulder
    spans a third of the trunk's own height.

    A direction that finds nothing does not constrain the answer, so it is
    skipped; if **no** direction does, the ring is unbounded here and *r0* comes
    back unchanged.  There is deliberately no floor: a floor would report room
    that is not there, and the caller's whole question is whether the cap ends
    up under the skin (``CLAUDE.md`` 一之一).

    **One number, and that is this caller's question**, not a shortcut: it is
    choosing *where* to put a ring, so it wants the worst direction.  Sizing one
    is a different question and §7.289 measured what happens when a scalar
    answers it — see :func:`_fit_inside_surface`.
    """
    e1, e2 = _limb_frame(np.asarray(axis_dir, dtype=np.float64))
    th = 2.0 * math.pi * np.arange(rays) / rays
    dirs = np.cos(th)[:, None] * e1[None, :] + np.sin(th)[:, None] * e2[None, :]
    near, _cnt = _surface_reach(centre, dirs, torso)
    got = np.isfinite(near)
    if not got.any():
        return max(r0, 0.0)
    return max(min(r0, float(near[got].min()) - margin), 0.0)


def _fit_inside_ring(centre: np.ndarray, offs: np.ndarray, host: np.ndarray,
                     host_centre: np.ndarray, margin: float,
                     iters: int = 16) -> np.ndarray:
    """Per-vertex scale putting ``centre + k·offs`` inside the *host* ring.

    :func:`_ring_room` and §7.230's wrist clamp both answer with **one number**,
    and a limb section is not one number: it carries a squash and a 24-ray
    outline ratio, so a scalar agrees with the neighbour about a single
    direction and about no other.  Measured at the wrist, the scalar clamp
    pulled 21 of the palm's 24 rays in by up to 4.81 mm more than they had to
    come and still let **three** stand proud, by 0.82 mm — a rim right round a
    cap that §7.230 had already spent its own ring on burying (§7.289).

    Both rings are star-shaped about their own centres by construction (a sweep
    ring's offsets are radial and ``ratio`` scales them radially), so the host
    is read as a polar radius about *host_centre* and the query point is
    projected into the host ring's plane — that is a **cylindrical**
    containment, which is the right one here: the two rings are a few
    millimetres apart along a tube whose wall runs between them.

    ``margin`` is the caller's; this only changes what the margin is measured
    from.  A vertex already inside keeps ``k = 1``, so the clamp does nothing
    where nothing was wrong.
    """
    H = np.asarray(host, dtype=np.float64)
    c = np.asarray(host_centre, dtype=np.float64)
    rel = H - c[None, :]
    nrm = np.cross(rel, np.roll(rel, -1, axis=0)).sum(axis=0)
    ln = float(np.linalg.norm(nrm))
    if ln < 1e-18:
        return np.ones(len(offs))
    nrm = nrm / ln
    e1 = rel[0] - nrm * float(rel[0] @ nrm)
    n1 = float(np.linalg.norm(e1))
    if n1 < 1e-12:
        return np.ones(len(offs))
    e1 = e1 / n1
    e2 = np.cross(nrm, e1)
    hx, hy = rel @ e1, rel @ e2
    th = np.arctan2(hy, hx)
    rr = np.hypot(hx, hy)
    o = np.argsort(th)
    th_s, rr_s = th[o], rr[o]
    # wrapped so a query between the last and the first sample interpolates the
    # short way round rather than sweeping back across the whole ring
    th_w = np.concatenate([th_s - 2 * math.pi, th_s, th_s + 2 * math.pi])
    rr_w = np.concatenate([rr_s, rr_s, rr_s])

    def inside(q):
        r = q - c
        r = r - nrm * float(r @ nrm)
        d = float(np.hypot(r @ e1, r @ e2))
        if d < 1e-12:
            return True
        return d <= float(np.interp(math.atan2(float(r @ e2), float(r @ e1)),
                                    th_w, rr_w)) - margin

    centre = np.asarray(centre, dtype=np.float64)
    out = np.ones(len(offs))
    for i, off in enumerate(np.asarray(offs, dtype=np.float64)):
        if inside(centre + off):
            continue
        lo, hi = 0.0, 1.0
        if not inside(centre):
            # The ring's own centre is outside the host: there is no scale that
            # helps and quietly shrinking to nothing would be a made-up answer
            # (一之一).  Leave the vertex alone and let a ruler report it.
            out[i] = 1.0
            continue
        for _ in range(iters):
            mid = 0.5 * (lo + hi)
            if inside(centre + off * mid):
                lo = mid
            else:
                hi = mid
        out[i] = lo
    return out


def _fit_inside_surface(centre: np.ndarray, offs: np.ndarray, host: Mesh,
                        margin: float):
    """Per-vertex scale putting ``centre + k·offs`` under *host*'s skin.

    Returns ``(k, why)`` — ``why`` is empty when every vertex got an answer.

    The sibling of :func:`_fit_inside_ring` for the case where the neighbour is
    a **part** and not another station of the same tube.  The wrist's two rings
    are a few millimetres apart along one axis, so a ring can be read there as a
    polar radius; the ankle's neighbour is the foot, whose own sections are cut
    the other way round entirely (:data:`FOOT_SECTIONS` are planes of constant
    z, the leg's are horizontal), so the only thing that can answer "does this
    vertex end up inside" is the foot's surface along that vertex's own ray.

    Exact rather than bisected: :func:`_surface_reach` already returns the
    distance to the first exit, so ``k = (t − margin) / |off|`` *is* the answer
    and there is nothing to search.

    Two refusals, both reported rather than papered over (一之一):

    * the centre is not under the skin — parity says so — in which case no scale
      helps and shrinking to a point would be an invented answer;
    * a ray finds nothing, which means the surface is not in that direction and
      the vertex cannot be buried along it.

    Both leave ``k = 1``, so a ruler still sees the vertex standing proud.
    """
    offs = np.asarray(offs, dtype=np.float64)
    ln = np.linalg.norm(offs, axis=1)
    ok = ln > 1e-12
    out = np.ones(len(offs))
    if not ok.any():
        return out, "the ring has no extent"
    dirs = np.zeros_like(offs)
    dirs[ok] = offs[ok] / ln[ok, None]
    near, cnt = _surface_reach(centre, dirs, host)
    # Parity over the rays that hit anything: a point inside a closed surface
    # crosses it an odd number of times whichever way it looks.  A majority,
    # not any single ray, because a ray that grazes an edge is counted twice.
    live = cnt > 0
    if not live.any() or float(np.mean(cnt[live] % 2 == 1)) <= 0.5:
        return out, "the ring's centre is not inside that part"
    lost = int((~np.isfinite(near) & ok).sum())
    room = np.where(np.isfinite(near), near - margin, np.inf)
    out[ok] = np.clip(room[ok] / ln[ok], 0.0, 1.0)
    return out, (f"{lost} of {int(ok.sum())} rays found no surface"
                 if lost else "")


def _shift_sampler(fn, prepended: int):
    """Re-index an outline sampler after rings were added at the root.

    :func:`_outline_sampler` is closed over the sweep it was built from and is
    queried by **ring index**, so anything that lengthens the point list ahead
    of it moves every station one place — the wrist would be read at the
    forearm.  ``_contain_in_trunk`` (the leg's) returns the same number of
    points, which is why the leg never needed this and the arm does.
    """
    if fn is None or prepended <= 0:
        return fn

    def sample(i, offs):
        return fn(max(float(i) - prepended, 0.0), offs)
    # The frames are indexed by ring, so they move with it.  The prepended rows
    # repeat station 0's — they are behind the table's own start, where the
    # nearest measured value is the only claim available (:func:`palm_profile`
    # makes the same hold for the radii).
    fr = getattr(fn, "frames", None)
    if fr is not None:
        sample.frames = np.concatenate([np.repeat(fr[:1], prepended, axis=0),
                                        fr])
    return sample


def _contain_in_trunk(pts: np.ndarray, radii: np.ndarray, squash: np.ndarray,
                      torso: Mesh, prop: Proportions, side: str,
                      hip_y: float = -1e30):
    """Shrink the leg tube where it runs *inside* the trunk, so it stays inside.

    Above the hip joint the tube is not skin — the trunk's surface is — and
    measured, ours came out wider than the trunk over that whole stretch
    (+9.8 mm at the tube's top ring at 0.619 of stature).  Where it pokes
    through, the two surfaces cross at a shallow angle and the crossing curve is
    the seam down the outer hip.

    What it is clamped to is the trunk's **own** outline at that height, read
    off the finished mesh rather than off the profile table, so the band scales,
    the posture bend and the glute deformer are all already in it.

    **Only above** *hip_y* (:func:`hip_joint_height`), and that bound is the
    whole of §7.194.  This used to run over the entire tube, on the strength of
    a sentence in this docstring: "it cannot cost the hip its width either — the
    trunk it clamps against has already taken the union with the leg envelope in
    every direction".  That claim is false, and it is **circular**: below the hip
    joint the trunk's outline *is* the union with this very tube, resampled onto
    a 44-gon of rays from the trunk's own centre, so what the clamp finds is the
    leg's own reach less the ring's chord loss — and it then shaves that off the
    leg, plus the margin, every time.  Measured on the shipped body: the two
    stations N10 was reported at lost **14.1% and 14.6%** of the thigh's radius
    (72.5 → 62.3 mm at 0.523 of stature, 74.0 → 63.2 at 0.498) against a table
    that says 81.6 mm, and the ray from the body axis grazes the surface there,
    so that is where the −33 mm came from.  With the bound in place the same
    band goes from 8.78 mm mean / −33.27 worst to 3.26 / −8.53 (§7.194 三).

    §7.169 measured this once already, from the other side: clamping the leg back
    to the trunk cost 13% of the hip's width, "because the skin at the hip *is*
    the thigh".  The clamp went in anyway, with the sentence above standing in
    for the check.

    **Width only, and the depth follows it.**  Clamping the two semi-axes
    independently was tried and is worse (§7.192): below the hip joint the
    trunk's own z extent *is* the closure chord this whole band is short in, so
    a depth clamp reads our own defect back onto the thigh — the front
    diagonals at 0.500 of stature went from −33 to −41 mm and the closure band's
    mean from 8.6 to 12.1.  That defect is the same circularity as the one above;
    the bound now keeps both of them out of this band.
    """
    y_lo = max(float(torso.positions[:, 1].min()), float(hip_y))
    sgn = 1.0 if side == "L" else -1.0
    tp = torso.positions.astype(np.float64)
    keep = (tp[:, 0] * sgn) > 0.0
    out = np.array(radii, dtype=np.float64)
    # A margin, not a fitted number: it only has to exceed the surfaces' own
    # sampling so the two never touch.  0.002 of stature is 3.1 mm here,
    # and it is :data:`TRUNK_CLAMP_MARGIN` because the other clamp on this
    # same tube (:func:`_clamp_to_trunk_table`, below the hip joint) has to
    # leave the same room -- two clamps with two margins drift.
    margin = TRUNK_CLAMP_MARGIN * prop.height
    for i, pt in enumerate(np.asarray(pts)):
        y = float(pt[1])
        if y < y_lo:
            continue
        # About one and a half of the trunk loft's rings (its spacing is 0.0065
        # of stature here).  Wider and the trunk's own taper gets into the
        # answer: it narrows going down, so a tall band reports the widest
        # height in it and the clamp stops binding where it is needed most.
        band = keep & (np.abs(tp[:, 1] - y) < 0.010 * prop.height)
        if band.sum() < 4:
            continue
        room = float(np.abs(tp[band, 0]).max()) - abs(float(pt[0])) - margin
        # Never below a third: this is interior geometry either way, and a tube
        # pinched to nothing would tug its skinned neighbours in with it.
        out[i] = float(np.clip(room, 0.35 * out[i], out[i]))
    return out, np.asarray(squash, dtype=np.float64)


# How many stations the descent into the foot is sampled with.  A sampling
# density, not a measurement — what the two ends of the stretch are is measured
# (:func:`_reach_into_foot`), how finely it is cut is this.
FOOT_REACH_RINGS = 2


def _reach_into_foot(pts, radii, squash, ratio, axis, sides: int, foot: Mesh,
                     prop: Proportions):
    """Carry the leg's sweep down into the foot and bury its mouth there.

    ``(pts, radii, squash, ratio, axis, note)``.

    The chain runs out at ``cf_j_leg03`` and :data:`LEG_SECTIONS` with it, but
    the tube is still in the open there — measured, at the chain's own end
    **23 of the 24 vertices** of its ring are outside the foot and so is the
    ring's centre, so a cap there is a disc hanging in mid air.  It has to carry
    on until it is under the foot's skin.

    **Both halves of that used to be typed** (§7.290).  Two heights (0.030 and
    0.018 of stature) and a taper onto ``FOOT_SECTIONS[3][1]``, which is the
    foot's half-width at the ankle station — a number measured at y = 0.0271 of
    stature and spent at 0.0300 and 0.0180, §7.176's slab in miniature.  The
    sentence that justified them ("the chain sits 0.0489 of stature up while the
    foot's own surface stops at 0.0409 — a 13.6 mm gap") stopped being true when
    §7.215 lifted the sole 14.55 mm: today the foot's top is **0.0495** and the
    gap is **−1.14 mm**.  What the typed pair left behind was a rim — 6 of the
    mouth's 24 vertices outside the foot, and outside **Origin** as well, which is
    what says the fix was never the foot's table.

    Measured in its place:

    * **where** — the roomiest place along the descent, exactly
      :func:`_reach_into_trunk`'s fallback and for the same reason.  Nowhere
      does the whole section fit (the best height keeps 16 of 24 rays, and the
      medial arch takes the rest), so "the outermost place it fits" has no
      answer and "the place that gives up least of the tube" is the one left.
      The curve is broad — 0.93 to 0.958 of the section retained over 20 mm of
      height — so this is not balanced on a knife edge.
    * **how wide** — the foot's own surface along each of the mouth's own rays
      (:func:`_fit_inside_surface`), because a section carries a squash and a
      24-ray outline and one number agrees with a neighbour about one direction
      and no other (§7.289 measured that at the wrist).

    Everything past :data:`LEG_TIP` **holds the last measured station** — radius
    and squash as well as ``t``, the convention every other column past a tip
    already follows — and then the clamp takes back only what the foot has no
    room for.  Nothing here aims at a table of the other part's.
    """
    pts = np.asarray(pts, dtype=np.float64)
    radii = np.asarray(radii, dtype=np.float64)
    squash = np.asarray(squash, dtype=np.float64)
    axis = np.asarray(axis, dtype=np.float64)
    tip = pts[-1].copy()
    sole = float(np.asarray(foot.positions, dtype=np.float64)[:, 1].min())
    margin = 0.002 * prop.height
    n = max(int(FOOT_REACH_RINGS), 1)

    # The added stations are past the table, so they hold the last measured
    # frame — the same flat hold their radii take.
    fr0 = getattr(ratio, "frames", None)
    fr = None if fr0 is None else np.concatenate(
        [fr0, np.repeat(np.asarray(fr0)[-1:], n, axis=0)])

    def descend(y: float):
        """The sweep with *n* stations from the tip straight down to *y*.

        Straight down, because the part it has to finish inside is the one below
        it and the chain has no more joints to follow.  The centre stays on the
        ankle's own x/z, which is where the foot is thickest around it.
        """
        add = np.repeat(tip[None, :], n, axis=0)
        add[:, 1] = np.linspace(float(tip[1]), float(y), n + 1)[1:]
        return (np.vstack([pts, add]),
                np.concatenate([radii, np.full(n, radii[-1])]),
                np.concatenate([squash, np.full(n, squash[-1])]),
                np.vstack([axis, add]))

    def mouth(y: float):
        p2, r2, s2, a2 = descend(y)
        ring = prim.sweep_rings(p2, r2, sides, squash=s2,
                                up_hint=(1.0, 0.0, 0.0), ratio=ratio,
                                frame_pts=a2, frames=fr)[-1]
        return p2, r2, s2, a2, ring - p2[-1]

    # A scan, not a bisection: "how much of the section survives" is not
    # monotone in the depth — the ankle pinches, the arch opens out below it and
    # closes again onto the sole — so the first place that improves is not the
    # best one.  Steps of about a ring's own spacing.
    best = None
    for y in np.linspace(float(tip[1]), sole, 33)[1:]:
        p2, r2, s2, a2, offs = mouth(float(y))
        fit, why = _fit_inside_surface(p2[-1], offs, foot, margin)
        if why.startswith("the ring's centre"):
            continue
        keep = float(np.mean(fit))
        if best is None or keep > best[0]:
            best = (keep, float(y))
    if best is None:
        # No height along the descent is under the foot's skin.  Said, not
        # papered over: a mouth left at the chain's end is a visible disc, and a
        # sweep quietly stopped short is a visible hole (一之一).
        return pts, radii, squash, ratio, axis, \
            "the leg's mouth found no height inside the foot"
    p2, r2, s2, a2, offs = mouth(best[1])
    fit, why = _fit_inside_surface(p2[-1], offs, foot, margin)
    base_ratio = ratio
    last = len(p2) - 1

    def clamped(i, offs):
        r = np.asarray(base_ratio(i, offs), dtype=np.float64)
        return r * fit if int(round(float(i))) == last else r
    if fr is not None:
        clamped.frames = fr

    return p2, r2, s2, clamped, a2, why


def reference_skeleton(sex: int, height: float, sliders: dict | None = None):
    """The reference armature at *height*, with the editor's body sliders played.

    ``(skeleton, note)``.  *sliders* is a ``{名稱: 0..1}`` subset of
    ``shape_cat.BODY_SHAPE_NAMES``; ``None`` skips the shape pass entirely and
    returns the prefab's own rest, ``{}`` runs it with every slider neutral.
    The skeleton is ``None`` when this machine has never converted an armature —
    said, not substituted (``CLAUDE.md`` 一之三).

    Lives here rather than in the tool that first needed it because the callers
    are now the generator's own: a body is authored against one of these and
    posed by another, and the two have to be the same armature, built the same
    way, for the inverse binds to line up at all.

    *sex* does not select a different armature and is not meant to: measured,
    the two bodies share a bind stature and every landmark ratio, and what
    separates them is the shape pass on top (§7.153).  It stays in the
    signature because the caller's *height* comes from a per-sex proportion.
    """
    from ..origin import rig as R
    from ..origin.figure import shape_anim, shape_apply as SA
    from ..origin.figure import shape_cat as SC, shape_run as SR
    from ..origin.figure import shape_update as SU
    from .skeleton import BIND_STATURE_M

    ref = R.rig()
    if not getattr(ref, "parents", None):
        return None, ("no reference armature on this machine "
                      "(UserData/config/origin_rig.json) — convert first")
    sk = Skeleton("ours")
    R.graft_full_skeleton(sk, ref, height / BIND_STATURE_M)
    if sliders is None:
        return sk, "reference armature, shape pass not run"

    names = list(SC.BODY_SHAPE_NAMES)
    vals = np.full(len(names), 0.5)
    for key, v in sliders.items():
        if key not in names:
            # **Raise, do not hand back a body.**  This used to ``return sk``
            # with the message in the note — and ``sk`` at that point is the
            # armature with the shape pass **never run**, which is a different
            # body, not a failed one.  Measured (§7.202): ``--slider
            # NotASlider=1`` moved the hand's chain 0.03613 → 0.03441 of
            # stature, the neutral pass's 1.05 showing up as a −4.8% reading,
            # and every other number on the page moved with it.  The note was
            # printed, in one clause of a header that always carries a note, so
            # what a typo produced was a full page of plausible measurements
            # (``CLAUDE.md`` 一之三: 載入失敗就報錯，永遠不准偷生一個頂替).
            near = [n for n in names if key.lower() in n.lower()
                    or n.lower() in key.lower()]
            raise KeyError(
                f"no such body slider: {key!r} — the editor has "
                f"{len(names)} and this is not one of them"
                + (f"; did you mean {', '.join(near)}?" if near else
                   " (shape_cat.BODY_SHAPE_NAMES lists them)"))
        vals[names.index(key)] = v

    class _Stub:
        def body(self):
            return {"typeBone": 0}

        def face(self):
            return {}

    ctx = SR.body_context(_Stub(), sk)
    # ``skip_bones`` is not optional here.  ``apply_body_shape`` passes
    # ``shape_run.SKIP_BONES``, and calling the shared helper without it lets the
    # height slider write ``cf_n_height``'s uniform scale — which the graft has
    # already applied (§7.9), so it lands twice and the whole figure comes back
    # 8% smaller.  The symptom was every slider, ``Hip`` and ``BustSize``
    # included, returning the same shrunken landmarks: a physically impossible
    # reading, which is the fastest kind to spot (``CLAUDE.md`` 七).
    # ``unit`` scales the pass's **position** writes (``shape_run._set_position``
    # multiplies by it), and the card path has always passed the graft's own
    # scale (``dress.py``: ``apply_body_shape(…, rig_scale)``).  This one passed
    # **1.0**, so the pass placed bones at Origin's native metres on a figure the
    # graft had already resized.
    #
    # The pass translates exactly one chain — measured across three statures,
    # ``cf_s_siri``/``cf_s_waist02``/``cf_s_thigh01``/``cf_s_neck``/``cf_s_arm01``
    # move **0.00 mm** and only ``cf_s_bust*``/``cf_j_bnip*`` move at all, which
    # is the chain that rests on the midline (§7.172).  Its displacement came
    # back **95.06 / 90.56 / 88.11 mm at heights 1.30 / 1.5564 / 1.7113**: near
    # constant where it should have been proportional, so as a fraction of
    # stature the bust sat at 0.0731 / 0.0582 / 0.0515 — a short figure's bust
    # chain pushed **42% further out relative to her own size** than a tall
    # one's.  Our surface is built from stature-relative tables, so the bone
    # walked out of the breast: at the default 1.5564 the mesh stopped 21 mm
    # short of ``cf_j_bnip02``, which is why F0-2 (i) could not simply put a
    # nipple where the bone is (§7.203).
    #
    # ``BIND_STATURE_M`` is Origin's own, so this is exactly 1.0 there and every
    # number ever measured at that stature is unchanged by it.
    rep = SA.apply_shape(sk, vals, SC.body_rows(), shape_anim.body_curves(),
                         SU.BODY_UPDATE, ctx, height / BIND_STATURE_M,
                         label="體型", skip_bones=SR.SKIP_BONES)
    return sk, rep.describe()


def bind_skeleton(sex: int, height: float):
    """The armature our body is **authored against** — the neutral shape pass.

    Not the prefab's rest, which is what this used to be.  Origin's own
    ``o_body_a`` does not bind every bone at that rest: of its 134 skin bones,
    86 have ``bindpose == inverse(prefab rest)`` but the six ``cf_s_bust*``
    have ``bindpose == inverse(rest **after** the neutral pass)`` — measured,
    ``shaped_world · bindpose`` is the identity on those and the pass moves
    Origin's 659 bust vertices a median 0.67 mm (§7.172).

    The reason is visible in the rest itself: the whole bust chain sits on the
    midline at x = 0 there, and it is the shape pass that carries it out to the
    breast.  A vertex bound to a midline bone with the *prefab's* inverse bind
    is therefore thrown sideways the moment anything runs the pass — ours went
    87 mm, which put a 63% wider chest on every measurement taken after it and
    read like a generator fault rather than a binding one.

    So the body is built and skinned here, where Origin's own mesh is bound.  The
    consequence to keep in mind: the neutral figure is now the **shaped** one,
    and the profile tables were measured on the raw bind (§7.160), so they are
    3–6% off their target until they are re-measured with ``--shaped``.
    """
    return reference_skeleton(sex, height, {})


# --------------------------------------------------------------------------
# Our UV atlas.  **Our** coordinates — Origin's unwrap is theirs, and copying it
# vertex by vertex is copying the asset with a change of container
# (``CLAUDE.md`` 一之四之一).  What is taken from Origin is the *shape of the
# design*, which is a fact about the structure and measurable:
#
#   * the body splits into a few long islands with ``v`` running up the figure
#     (measured on ``o_body_a``: the three tall islands correlate v-to-height
#     +0.997/+0.998/+0.998 — §7.178);
#   * each arm is its own island and carries its hand (Origin's #2/#3 hold
#     arm 414 + hand 851);
#   * the feet ride with the legs (Origin's #1/#5/#6 each hold torso + leg + foot).
#
# The split between them is **our** measurement of **our** surface: area per
# part, which comes out at leg 43.4%, torso 31.6%, arm 15.1%, hand 5.6%,
# foot 4.3% — and lands within 1.3 points of Origin's own split (44.6/30.3/13.0/
# 5.0/5.2), so an atlas cut this way gives each part the same texel density the
# game does without using any of its numbers.
#
# Before this every part was unwrapped to the **whole sheet** and they all sat
# on top of each other: 60,160 shared texels between every pair, occupancy
# 0.9688 against Origin's 0.4384.  A body like that cannot wear any texture at all
# — each part samples the same pixels (§7.179).
#
# Each island's **area** is its share of the surface and its **aspect** is the
# part's own stretch, so one texel covers the same amount of skin everywhere.
# Both come off our own mesh:
#
#   part    area m²   du→m    dv→m   aspect       island w × h
#   torso   0.5142   1.8189  0.6389   0.883      0.487 × 0.551
#   leg     0.3529   1.1892  1.0647   0.285      0.229 × 0.804   (each)
#   arm     0.1228   0.8443  1.4095   0.338      0.147 × 0.436   (each)
#   hand    0.0459   0.1857  0.3656   0.789      0.138 × 0.174   (each)
#   foot    0.0353   0.4804  2.3950   0.569      0.102 × 0.180   (each)
#
# ``du→m`` / ``dv→m`` are the median 3D length one unit of u / of v buys, read
# off the UV jacobian of each triangle.  The first cut of this atlas used the
# area alone and left the torso's checker as **flat bands** — its island was
# 0.31 wide against a body that is 2.85× longer round than it is tall in that
# parameterisation, so a square texel became a 1:2.8 smear.
#
# 0.008–0.013 of margin between islands so bilinear filtering at the edge of one
# does not reach into the next.  Occupancy comes out 0.849.
UV_ATLAS = {
    "torso":  (0.000, 0.000, 0.487, 0.551),
    "leg_L":  (0.500, 0.000, 0.729, 0.804),
    "leg_R":  (0.737, 0.000, 0.966, 0.804),
    "arm_L":  (0.000, 0.560, 0.147, 0.996),
    "arm_R":  (0.155, 0.560, 0.302, 0.996),
    "hand_L": (0.310, 0.560, 0.448, 0.734),
    "hand_R": (0.310, 0.742, 0.448, 0.916),
    "foot_L": (0.500, 0.812, 0.602, 0.992),
    "foot_R": (0.610, 0.812, 0.712, 0.992),
}


def _extend_to_zero(keys: list) -> list:
    """Carry a profile column down to ``t = 0`` along its own slope.

    ``TORSO_UNMEASURED_T`` drops the t = 0.0208 row because that section is not
    the trunk (§7.176), and ``prim.smooth_profile`` **clamps** below its first
    key — so the loft held the t = 0.0625 section flat all the way to the base.
    Measured, three rows came back with identical radii (back reach 0.07751 and
    rmax 0.10951 at 0.518 *and* 0.526 of stature, Δ = 0.00000): a 2.2 cm
    cylinder welded onto a surface that was still narrowing, and the curvature
    break shades as **a hard line across the buttocks** — the same place §7.169
    P2 cleared once (rows 370–373).

    Extrapolating from the two nearest measured stations is not inventing a
    number: it is the trend those two carry.  Guessing would be picking a value
    because the picture improved.
    """
    if len(keys) < 2 or keys[0][0] <= 1e-9:
        return list(keys)
    (t0, v0), (t1, v1) = keys[0], keys[1]
    slope = (v1 - v0) / max(t1 - t0, 1e-9)
    return [(0.0, v0 - slope * t0)] + list(keys)


def place_uv(mesh: Mesh, rect) -> None:
    """Rescale a part's own 0..1 parameterisation into its slot in the atlas.

    The sweeps and the loft each hand back ``u`` round and ``v`` along, which is
    the right *shape* for an island — what was missing is that they all handed
    back the same rectangle.
    """
    uv = getattr(mesh, "uvs", None)
    if uv is None or not len(uv):
        return
    uv = np.asarray(uv, dtype=np.float64)
    lo, hi = uv.min(axis=0), uv.max(axis=0)
    span = np.maximum(hi - lo, 1e-9)
    n = (uv - lo) / span
    u0, v0, u1, v1 = rect
    mesh.uvs = np.stack([u0 + n[:, 0] * (u1 - u0),
                         v0 + n[:, 1] * (v1 - v0)], axis=-1).astype(np.float32)


#: Parts the welder may **not** trim or stitch, because each already has its
#: own join: the leg and the foot are unioned into the trunk by smooth max
#: (§7.222／§7.224), the wrist is a one-to-one pair that already fits (§7.251),
#: the palm's distal end is a branch no pairwise stitch can make (§7.283), and
#: the nails are an applied shell Origin has no geometry for at all (§7.144).
#: Named so a ruler can ask what the welder *would* see there
#: (``--openings``) without a throwaway copy of the trim — §7.243 and §7.267
#: both needed exactly that and both rebuilt it in a script.
WELD_SKIP = ("nail", "leg", "foot", "hand")


def build_body_mesh(p: dict, sex: int = 0, skel: Skeleton | None = None,
                    prop: Proportions | None = None,
                    record: dict | None = None,
                    weld_skip=None, forks=None) -> tuple[Mesh, list[str]]:
    """The whole skin — torso, limbs, hands, feet — and a segment name per vertex.

    Nothing called this before: the torso loft and the limb profiles were built
    for the cloth and genital code to measure against, and ``build_hand`` /
    ``build_foot`` had no call sites at all.  A generator whose output is never
    assembled cannot be measured, and F0-2's acceptance is exactly that —
    running our mesh through the same ruler as Origin's (``tools/body_profile.py``).

    This is **not** a fallback for a card that failed to load (``CLAUDE.md``
    一之三): it builds only when something asks for it by name.

    The labels match ``body_profile.SEGMENTS`` so the two meshes are sectioned
    the same way; a horizontal slab through a T-pose shoulder catches both arms
    and returns the arm span, so which vertices belong to the trunk has to be
    decided before any section is taken.

    Every piece is bound to bones as it is built (:data:`SKIN_CHAINS`).  The
    third return is the list of bones the skeleton did not have — empty on a
    grafted reference armature, and the whole chain set on the bare procedural
    scaffold, which is the difference between a body the editor's sliders can
    shape and one they cannot touch (§7.162).
    """
    from .skeleton import FINGERS

    prop = prop or build_proportions(p, sex)
    skel = skel or build_humanoid(prop)
    out = Mesh("body")
    seg: list[str] = []
    absent: list[str] = []
    # **The sweeps' own stations, for whoever has to ask which ring a vertex
    # is on** (:data:`primitives.RING_TAP`, §7.317).  Only when the caller asked
    # for a record — the drawing path passes none and pays nothing — and the
    # previous value is restored rather than cleared, so a nested build cannot
    # steal an outer one's tap.
    tap0 = prim.RING_TAP
    col0 = prim.COLLAPSE_TAP
    if record is not None:
        prim.RING_TAP = []
        prim.COLLAPSE_TAP = []

    def add(mesh: Mesh, label: str, chain=None, rigid=None, chains=None,
            smooth: bool = False, uv: str | None = None, anchor="",
            anchors=None) -> None:
        rect = UV_ATLAS.get(uv or label)
        if rect is not None:
            place_uv(mesh, rect)
        if chain:
            # *label* is the chain's name, which is the key :data:`CHAIN_BRANCH`
            # is on.  It was not forwarded, so only the trunk — whose binder is
            # called directly below — could ever have a branch, and a table
            # added for any other chain would have been read by nobody
            # (七: a generic mechanism reached through a hand-kept list).
            absent.extend(weight_along_chain(mesh, skel, list(chain), sex,
                                             anchor, chain=label,
                                             height=prop.height,
                                             smooth=smooth))
        elif chains:
            absent.extend(weight_to_nearest_chain(mesh, skel, chains, sex,
                                                  anchors))
        elif rigid:
            absent.extend(weight_to_nearest(mesh, skel, list(rigid)))
        before = out.vertex_count
        out.append(mesh)
        seg.extend([label] * (out.vertex_count - before))

    torso = build_torso(p, prop, sex, skel=skel)
    # **All four of the trunk's shaping bones are branches of this chain**
    # (:data:`CHAIN_BRANCH`), so they are bound here by the same binder and from
    # the same kind of measured table as the shoulder.  Each used to be handed
    # over afterwards from the deformer's own region weight scaled to a measured
    # peak — and a peak is not a falloff: our breast skin rode ``cf_s_bust03``
    # out to 120 mm where Origin's stops at 80 (§7.278), and the hip's ramp gave
    # ``cf_s_thigh01`` nothing where Origin gives 0.272 and stretched into a fin
    # under a 45° bend.  What the buttock and the hip needed on top of distance
    # was **direction** (§7.279).
    absent.extend(weight_along_chain(torso, skel, list(SKIN_CHAINS["torso"]),
                                     sex, chain="torso", height=prop.height,
                                     smooth=True))
    add(torso, "torso")
    # The nipples, after the torso so they union onto a finished breast.
    #
    # Weighted **along the chain**, not rigidly to the nipple bones: the base
    # has to stay with the breast while the tip goes with ``cf_j_bnip02``, and
    # that is what ``AreolaBulge`` / ``NipWeight`` / ``NipStand`` write to.  A
    # rigid bind would tear the base off the skin the moment ``BustSize`` moved.
    #
    # **Skipped, and reported, when the armature has no bust chain.**  This ran
    # unconditionally and ``nipple_profile`` walks ``LIMB_AXIS["nipple"]``, so
    # the bare procedural scaffold — which carries none of the ``cf_s_*``
    # shaping bones (§7.162) — came out of here as a raw ``KeyError`` on
    # ``cf_s_bust03_L``.  That is neither of the two things ``CLAUDE.md`` 一之三
    # allows: it is not a report and it is not a declared own-asset path, it is
    # the female body failing to build at all on the machine F0 is for.  The
    # report channel already exists and every other piece here uses it —
    # ``absent`` is what this function returns for exactly this.
    # **Female only, and that is a measurement** (§7.254).  ``body_m`` carries
    # the same four nipple bones (§7.172 found them), and every one of them
    # carries **0 vertices and 0.000 weight** — nothing on that mesh is skinned
    # to the chain at all.  The skin is not there either: both ends of the axis
    # are **outside** the male mesh (five-ray parity, on the raw bind as well as
    # the shaped one, so it is not the neutral pass misplacing them the way
    # §7.203 once did), the nearest skin to ``cf_j_bnip02`` is 34.21 mm away,
    # and every one of 26 stations perpendicular to the axis finds no outline.
    # Nor is it somewhere else on his chest: through
    # ``--limb nipple --skin torso`` the relief about the axis line peaks at the
    # **5-10 mm ring, not the innermost** and falls away with the ribcage's own
    # curvature, where the female's peaks at the centre (+25.24 mm against
    # +21.64 one ring out) and drops 41 mm over 60.  A smooth chest, in other
    # words — Origin's male nipple is painted on, like its fingernails (§7.230).
    if sex == 0:
        for side in ("L", "R"):
            need = [n.format(s=side) for n in LIMB_AXIS["nipple"]]
            gone = [n for n in need if not skel.has(n)]
            if gone:
                absent.extend(gone)
                continue
            npts, nrad, nsq, napex, nfr = nipple_profile(p, skel, prop, side)
            add(prim.tube_along(npts, nrad, detail.even(12, 8),
                                f"nipple_{side}", squash=nsq, caps=True,
                                end_apex=napex, frames=nfr),
                "nipple",
                chain=[n.format(s=side) for n in NIPPLE_CHAINS["nipple"]],
                anchor=CHAIN_ANCHOR["nipple"].format(s=side),
                uv="torso")
    # Each limb's ring follows **its own** table's ray count (§7.236).
    arm_sides = limb_sides(len(ARM_OUTLINE[0][1]))
    leg_sides = limb_sides(len(LEG_OUTLINE[0][1]))
    for side in ("L", "R"):
        arm_chain = [n.format(s=side) for n in SKIN_CHAINS["arm"]]
        leg_chain = [n.format(s=side) for n in SKIN_CHAINS["leg"]]
        pts, radii, squash, ratio, axis = arm_profile(p, skel, prop, side)
        n0 = len(pts)
        pts, radii, squash = _reach_into_trunk(pts, radii, squash, torso,
                                               prop, side, 0)
        # The stub is a straight extension, so it carries the same frame as the
        # first real station — prepending it to both keeps the two polylines the
        # same length, which is what ``frame_pts`` needs.
        axis = np.vstack([np.repeat(pts[:1], len(pts) - n0, axis=0), axis])
        ratio = _shift_sampler(ratio, len(pts) - n0)
        # **Capped at the shoulder, open at the wrist** (§7.285).  The root cap
        # is inside the trunk (:func:`_reach_into_trunk` puts it where a ring of
        # this size fits), so it obeys §7.230.  The wrist cap cannot: the palm
        # starts there, and once both tables take the wrist from the union of
        # the two labels the two rings are the **same section** — 0.01706 x
        # 0.00974 against 0.01691 x 0.00977, 0.9% and 0.3% apart.  Two caps that
        # each need the other part to be wider at a station where the two are
        # equal is not a clamp that has not been tuned, it is a pair with no
        # solution, and §7.230's clamp already spends the palm's side of it.
        #
        # Measured, the lid was the whole of the defect and not its position:
        # with the union rows the cap's 25 vertices sit **0.10 mm** from Origin's
        # surface (p90 0.28, max 0.65 — it was 6.72 before), and 100% of them
        # are still more than 30° out, median **100.5°**, because a fan across
        # the mouth of a tube points down the tube.  Dropping it leaves the
        # sweep's own ring, whose normals are the wall's.
        #
        # Nothing can see into the mouth: the palm's tube carries on distally
        # from 6 mm behind this plane at the same radius, so a line of sight
        # into the opening has to come from the far side of the hand.  This is
        # not §7.251's weld — that measured a **collar** between the two rings
        # and every ruler said no; nothing here adds geometry.
        add(prim.tube_along(pts, radii, arm_sides, f"arm_{side}", squash=squash,
                            caps=(True, False), ratio=ratio, frame_pts=axis,
                            frames=getattr(ratio, "frames", None)),
            "arm",
            chain=arm_chain, smooth=True, uv=f"arm_{side}",
            anchor=CHAIN_ANCHOR["arm"].format(s=side))
        pts, radii, squash, ratio, axis = leg_profile(p, skel, prop, side,
                                                      sex)
        radii, squash = _contain_in_trunk(pts, radii, squash, torso, prop,
                                          side, hip_joint_height(skel))
        # ``up_hint`` along **x**, so ``r1`` lands on the section's width and
        # ``r1 × squash`` on its depth — the axes the table was measured in.
        # The default hint puts the first frame's normal on z, and for a
        # near-vertical sweep parallel transport keeps it there, so the leg came
        # out rotated a quarter turn about its own axis: as deep as Origin is wide
        # and as wide as Origin is deep (measured at 0.075 of stature, ours 0.0408
        # wide × 0.0309 deep against Origin's 0.0253 × 0.0341).  A calf is deeper
        # than it is wide and ours was the other way round.  The arm is
        # horizontal and its default frame already lands right, so only this
        # one needs saying.
        # Capped **at both ends**, and both are interior geometry: above the
        # junction the tube runs inside the trunk, and an *open* ring that pokes
        # out through it shows its inside (the measured poke was 9.8 mm at the
        # top ring, the thin seam down the outer hip, §7.169).  The ankle's cap
        # is buried by :func:`_reach_into_foot` — which is why the foot is built
        # first: the mouth's depth and its width are both questions about the
        # foot's surface.
        #
        # This is **not** §7.285's wrist, and the difference was worth two
        # measurements (§7.290).  There the arm and the palm are two stations of
        # one axis, so the fix was to make both tables read the same section and
        # then drop a cap that nothing could see into.  Here the two parts meet
        # at right angles — the foot's sections are planes of constant z — so no
        # re-measuring makes the two rings agree, and the cap stays: dropping it
        # would open the mouth, and keeping the leg a closed volume is also what
        # lets ``buried_mask`` keep answering for everything hidden inside it.
        #
        # What §7.289 left here as the next step — ``FOOT_SECTIONS``' top rows
        # from the ``foot`` ∪ ``leg`` union — is wrong twice over, and both are
        # in §7.290: **none** of the six vertices standing outside the foot was
        # inside Origin either (so the foot's table was never too small), and that
        # union has no meaning in this ruler anyway, because a plane of constant
        # z through a standing figure cuts the whole leg (+56 mm of half-width,
        # a section top 820 mm up at the hip).
        foot_rec: dict = {}
        foot = build_foot(p, skel, prop, side, record=foot_rec)
        # A fork that did not build leaves a hole, so it belongs beside the
        # missing skin bones rather than in a dict nobody reads (§7.300).
        for why in foot_rec.get("fork_refused", ()):
            absent.append(f"foot_{side}: the {why} fork is not two arcs")
        for why in foot_rec.get("fork_absent", ()):
            absent.append(f"foot_{side}: {why}")
        for why in foot_rec.get("fork_warn", ()):
            absent.append(f"foot_{side}: fork {why}")
        pts, radii, squash, ratio, axis, why = _reach_into_foot(
            pts, radii, squash, ratio, axis, leg_sides, foot, prop)
        if why:
            absent.append(f"leg_{side}: {why}")
        add(prim.tube_along(pts, radii, leg_sides, f"leg_{side}", squash=squash,
                            caps=True, up_hint=(1.0, 0.0, 0.0), ratio=ratio,
                            frame_pts=axis,
                            frames=getattr(ratio, "frames", None)),
            "leg", chain=leg_chain, smooth=True, uv=f"leg_{side}",
            anchor=CHAIN_ANCHOR["leg"].format(s=side))
        # Five chains and a palm, not thirteen loose bones (§7.271).  Which
        # digit a vertex belongs to is still decided by the nearest bone; what
        # changed is that the handover along a finger now follows Origin's measured
        # share instead of falling at the midpoint between two knuckles.
        digits = [[n.format(s=side) for n in DIGIT_CHAINS[f]]
                  for f, _n in FINGERS] + [[f"cf_s_hand_{side}"]]
        # The palm's own chain has no anchor: it *is* what the five anchor to.
        digit_anchors = [CHAIN_ANCHOR[f].format(s=side)
                         for f, _n in FINGERS] + [""]
        hand_rec: dict = {}
        hand = build_hand(p, skel, prop, side, record=hand_rec, forks=forks)
        # **A fork that did not build has to be heard.**  ``record`` is
        # ``build_hand``'s private channel for the nail indices, so anything else
        # it puts there is dropped on the floor — which is 一之一's "退了卻不說"
        # with a new spelling, and it is how §7.300's first three runs reported
        # nothing at all.  A refused fork leaves the trunk open, so it belongs in
        # ``absent`` beside the missing skin bones.
        for why in hand_rec.get("fork_refused", ()):
            absent.append(f"hand_{side}: the {why} fork is not two arcs")
        for why in hand_rec.get("fork_absent", ()):
            absent.append(f"hand_{side}: no ring to fork {why} off")
        for why in hand_rec.get("fork_warn", ()):
            absent.append(f"hand_{side}: fork {why}")
        before = out.vertex_count
        add(hand, "hand", chains=digits, uv=f"hand_{side}",
            anchors=digit_anchors)
        # Relabelled after the fact rather than added as a separate part: the
        # nails are welded into the hand's own mesh and its UV island, and
        # splitting them out would give them their own island for a label that
        # only a ruler reads.
        for i in hand_rec.get("nail", ()):
            seg[before + i] = "nail"
        # The same mesh the leg's cap was sunk into, not a second build of it —
        # two copies would be two answers to "is this cap inside the foot".
        add(foot, "foot",
            chains=[[n.format(s=side) for n in FOOT_CHAINS["foot"]]],
            uv=f"foot_{side}")
    # **One surface, not a pile of intersecting ones** (N25 (c)).  Every part
    # above is a closed volume and they used to be joined by simply crossing,
    # which is why 132 of Origin's 176 deltoid vertices lay inside neither our arm
    # nor our trunk (§7.237): the flesh at a junction is what two crossing tubes
    # do not have.  ``weld`` trims what is interior and sews the openings, using
    # only vertices that already exist — so ``seg`` stays aligned and every UV
    # and skin weight comes along untouched.
    #
    # Measured (§7.239 built it and the picture vetoed it; §7.240 found the two
    # reasons): skin **21 pieces → 8**, ``--gaps`` overall p90 **3.87 → 2.64 mm**
    # and the deltoid's **10.47 → 4.50**.  The nails sit it out — they are an
    # applied feature, not skin, and welding an ellipsoid's poles by position
    # makes them non-manifold on their own (90 of the first pass's 94 bad edges).
    # **Welded at the shoulder, and only there** — because that is the one
    # junction with nothing else joining it (§7.243).  ``build_torso`` already
    # unions the trunk with the **leg** envelope by smooth max (§7.222, §7.224),
    # so trimming and stitching the hip replaces a good join with a coarse
    # strip: measured, doing it everywhere costs the hip band >30° **3.6 → 15.4%**
    # and normals p90 19.8° → **62.5°**.  Nothing unions the **arm**, which is
    # why 132 of Origin's 176 deltoid vertices lay inside neither part (§7.237).
    #
    # So the rule is not "weld everything", it is **weld what is not already
    # joined**, and each name here is a junction that has its own construction:
    # the leg and foot have the union, the hand is a 1-to-5 branch a pairwise
    # stitch cannot do, the nails are an applied shell (Origin has no nail geometry
    # at all).  Measured against welding them too, this is the setting where no
    # band gets worse.
    from . import weld as _weld
    # **The wrist stays out too, and that was measured rather than assumed**
    # (§7.251).  It is the one junction left that is a clean one-to-one pair
    # (the arm's 26-vertex ring against the palm's, 9–12 mm apart), so it looked
    # like the next thing the §7.248 band could take.  It is not: the two rings
    # are the **same radius** (19.8 against 19.6 mm), which is the definition of
    # a junction with no gap in it — the flesh §7.237 found missing at the
    # shoulder has no counterpart here.  Welding it replaces an intersection
    # that already fits with a one-row collar, and every ruler says so:
    # ``--vs-shape`` >30° overall **6.3 → 7.0%**, ``seg arm`` **3.6 → 6.5%**,
    # ``seg hand`` 18.6 → 20.5%, ``--gaps`` hand p90 1.74 → 1.88 and >2 mm
    # 7.1 → 8.6%.  Same sentence as §7.243's hip: weld what is **not already
    # joined**.
    rep = _weld.weld(out, skip=np.array([t in (WELD_SKIP if weld_skip is None
                                                else tuple(weld_skip))
                                         for t in seg]),
                     labels=seg, collapse=SHOULDER_RIM_MERGE,
                     band=lambda *a, _s=sex: _shoulder_rings(*a, sex=_s),
                     record=record if record is not None else None)
    # The band's own vertices, labelled by the end they came from — a junction
    # is not a new body part and a new name here would quietly drop them out of
    # every ruler's section selection (``--vs-table`` and ``--field`` pick by
    # label), which is the wrong way to find out a label was added.
    seg.extend(rep.get("added") or ())
    if record is not None:
        record["weld"] = rep
    # **The trim leaves its vertices behind** (§7.304).  ``weld`` removes the
    # interior triangles and never touched the vertex arrays, so the body
    # shipped 237 vertices belonging to no triangle at all (male 230) — by
    # label, ``torso`` 115, ``arm`` 98, ``nipple`` 24.
    # Invisible on screen and not free anywhere else:
    # ``compute_normals`` leaves them a zero normal, ``--vs-shape`` reads a zero
    # normal as 90° out (24 of the nipple band's 28 vertices over 30° were
    # these), and they are in every "ours against Origin's" vertex ratio N20
    # spends.  ``seg`` is a per-vertex sidecar, so it is filtered by the same
    # mask; dropped is **reported**, not silently absorbed (一之一).
    # **Two causes, two numbers** (一之一).  Since §7.339 a loft merges the
    # samples a ring collapses onto one another — the trunk's rim walks the
    # rays that find no thigh to the axis (§7.219) and the grid used to put one
    # vertex there per ray — so the samples it merged land in this same count.
    # A trim's leftovers are a defect somebody may want to chase and a merged
    # sample is this construction working; one number for the two is what 七
    # keeps having to unpick.
    merged = sum(q for _nm, q in (prim.COLLAPSE_TAP or ()))
    keep = out.drop_unused()
    if not keep.all():
        gone = int((~keep).sum())
        seg = [s for s, k in zip(seg, keep.tolist()) if k]
        if record is not None:
            record["dropped_unused"] = gone
            record["dropped_trimmed"] = gone - merged
            record["dropped_collapsed"] = merged
            record["collapsed_by_loft"] = list(prim.COLLAPSE_TAP or ())
    out.normalize_weights()
    if record is not None:
        record["rings"] = prim.RING_TAP
    prim.RING_TAP = tap0
    prim.COLLAPSE_TAP = col0
    return out, seg, sorted(set(absent))


def build_body_model(p: dict, sex: int = 0
                     ) -> tuple[Model, Skeleton, Proportions, dict]:
    """Build the skeleton, the measurements, and an **empty** ``body`` part.

    The ``body`` part carries no geometry: a card replaces ``o_body_a``
    wholesale, so there is nothing to generate.  If the replacement never
    arrives the part stays empty and ``dress_character`` reports the failure;
    nothing silently substitutes a body for the one the card asked for.

    **The torso loft and the limb profiles are no longer built here.**  They
    were, and the reason given was "the genital and cloth code measures against
    them" — measured, that has not been true for some time: ``pieces`` had
    **zero readers** in the whole project (``BuiltCharacter`` stored it and
    nothing ever looked), ``sim/cloth.py`` does not import this module, the
    ``pieces`` in ``genitals.py`` is its own local, and the genitals themselves
    moved to the Origin body bake (一之三).  ``arm_profile`` / ``leg_profile`` /
    ``build_torso`` / ``torso_dims`` are called only from inside this file.

    It was not free: it put ``chara/builder.py → build_body_model →
    build_torso`` on the card path, so **every F0-2 change looked like it could
    reach card loading** and four regressions were run against a dependency
    that does not exist (§7.179 八 — and they came back identical every time,
    which is what a chain nobody reads produces).
    """
    prop = build_proportions(p, sex)
    skel = build_humanoid(prop)
    body = Mesh("body")
    model = Model("character", skel)
    model.add_mesh("body", body, skin_material(p), group="body", layer=0)
    return model, skel, prop, {"body": body}
